/// A turn carrying the owner's earlier message takes the new one in while
/// it runs, when the agent folds steered input into the turn in flight.
#[tokio::test]
async fn a_message_folds_into_a_turn_carrying_an_earlier_one_when_the_agent_takes_it() {
    let (engine, _tmp) = configured().await;
    let seg = open_segment(&engine).await;
    let batch = svc::create_batch(&engine.db.conn, engine.bot().await, seg, BatchKind::Delivery, None)
        .await
        .unwrap()
        .id;
    let first = engine.send_owner_message("first".into(), Vec::new(), None).await.unwrap();
    svc::move_owner_rows(
        &engine.db.conn,
        &[first.id],
        &[OwnerStatus::Queued],
        OwnerStatus::Delivered,
        Some(batch),
        Some(seg),
        svc::ReadMark::Read,
    )
    .await
    .unwrap();
    let mut rx = engine
        .manager
        .insert_test_connection_live("c", AgentType::ClaudeCode, None, EventEmitter::Noop)
        .await;
    {
        let state = engine.manager.get_state("c").await.unwrap();
        let mut s = state.write().await;
        s.native_steering_available = true;
        s.turn_in_flight = true;
        s.agent_info = Some(("claude-agent-acp".into(), "0.101.0".into()));
    }
    engine.begin_turn_for_test("c", seg, batch, BatchKind::Delivery, false, false).await;
    engine.set_turn_owner_rows_for_test(vec![first.id]).await;
    // The connection loop's part: take the steer.
    let taken = tokio::spawn(async move {
        match rx.recv().await {
            Some(ConnectionCommand::Steer { blocks, reply }) => {
                let _ = reply.send(Ok(SteerOutcome::Injected));
                (blocks, rx)
            }
            _ => panic!("expected a steer"),
        }
    });
    let second = engine
        .send_owner_message("second".into(), Vec::new(), Some(first.id))
        .await
        .unwrap();
    let (blocks, mut rx) = taken.await.unwrap();
    let text = blocks
        .iter()
        .find_map(|b| match b {
            crate::acp::types::PromptInputBlock::Text { text } => Some(text.clone()),
            _ => None,
        })
        .unwrap();
    // It carries its own time, as a delivery does (6.1).
    let (now_line, said) = text.split_once("\n\n").unwrap();
    assert!(now_line.starts_with("<codeg-now>") && now_line.ends_with("</codeg-now>"), "{text}");
    assert!(now_line.contains("this turn: the owner's message, sent while your turn ran"), "{text}");
    let first_at = first.created_at.with_timezone(&engine.owner_tz().await).format("%H:%M").to_string();
    assert!(
        now_line.contains("the owner's last message before this turn: ") && now_line.contains(&first_at),
        "{text}"
    );
    assert!(said.starts_with(&format!("[#{}, replying to #{}", second.id, first.id)), "{text}");
    assert!(text.ends_with("second"), "{text}");
    assert_eq!(second.status, Some(OwnerStatus::Delivered), "the turn's now");
    assert_eq!(second.batch_id, Some(batch));
    assert_eq!(second.data.as_ref().unwrap()["merged"], true);
    assert!(second.read_at.is_some());
    assert!(!engine.preempting_for_test().await, "nothing was stopped");
    // When that turn ends, both messages are answered.
    engine.feed_for_test("c", 1, turn_complete("end_turn")).await;
    let r2 = svc::get_row(&engine.db.conn, second.id).await.unwrap().unwrap();
    assert_eq!(r2.status, Some(OwnerStatus::Answered));

    // An adapter that never answers a folded prompt: the message waits.
    let batch2 = svc::create_batch(&engine.db.conn, engine.bot().await, seg, BatchKind::Delivery, None)
        .await
        .unwrap()
        .id;
    {
        let state = engine.manager.get_state("c").await.unwrap();
        let mut s = state.write().await;
        s.turn_in_flight = true;
        s.agent_info = Some(("claude-agent-acp".into(), "0.86.0".into()));
    }
    engine.begin_turn_for_test("c", seg, batch2, BatchKind::Delivery, false, false).await;
    engine.set_turn_owner_rows_for_test(vec![first.id]).await;
    let third = engine.send_owner_message("third".into(), Vec::new(), None).await.unwrap();
    assert_eq!(third.status, Some(OwnerStatus::Queued));
    assert!(rx.try_recv().is_err(), "no steer went out");
}

#[test]
fn only_adapters_that_answer_a_folded_prompt_take_one() {
    use super::engine::steering_answers_folded_input;
    let claude = |v: &str| Some(("claude-agent-acp".to_string(), v.to_string()));
    assert!(!steering_answers_folded_input(claude("0.86.0").as_ref()));
    assert!(!steering_answers_folded_input(claude("0.65.0").as_ref()));
    assert!(steering_answers_folded_input(claude("0.87.0").as_ref()));
    assert!(steering_answers_folded_input(claude("0.101.0").as_ref()));
    assert!(!steering_answers_folded_input(claude("not a version").as_ref()));
    let scoped = Some(("@agentclientprotocol/claude-agent-acp".to_string(), "0.80.0".to_string()));
    assert!(!steering_answers_folded_input(scoped.as_ref()));
    let codex = Some(("codex-acp".to_string(), "2.4.0".to_string()));
    assert!(steering_answers_folded_input(codex.as_ref()));
    assert!(steering_answers_folded_input(None));
}

/// With attachments, the blocks are the whole of what goes over the wire:
/// the message's text leads them.
#[tokio::test]
async fn a_folded_message_with_attachments_leads_with_its_text() {
    let (engine, _tmp) = configured().await;
    let seg = open_segment(&engine).await;
    let batch = svc::create_batch(&engine.db.conn, engine.bot().await, seg, BatchKind::Delivery, None)
        .await
        .unwrap()
        .id;
    let first = engine.send_owner_message("first".into(), Vec::new(), None).await.unwrap();
    let mut rx = engine
        .manager
        .insert_test_connection_live("c", AgentType::ClaudeCode, None, EventEmitter::Noop)
        .await;
    {
        let state = engine.manager.get_state("c").await.unwrap();
        let mut s = state.write().await;
        s.native_steering_available = true;
        s.turn_in_flight = true;
        s.agent_info = Some(("codex-acp".into(), "2.5.0".into()));
    }
    engine.begin_turn_for_test("c", seg, batch, BatchKind::Delivery, false, false).await;
    engine.set_turn_owner_rows_for_test(vec![first.id]).await;
    let taken = tokio::spawn(async move {
        match rx.recv().await {
            Some(ConnectionCommand::Steer { blocks, reply }) => {
                let _ = reply.send(Ok(SteerOutcome::Injected));
                blocks
            }
            _ => panic!("expected a steer"),
        }
    });
    let image = crate::acp::types::PromptInputBlock::Image {
        data: "aGk=".into(),
        mime_type: "image/png".into(),
        uri: None,
    };
    let second = engine
        .send_owner_message("use this screenshot".into(), vec![image], None)
        .await
        .unwrap();
    let blocks = taken.await.unwrap();
    assert_eq!(blocks.len(), 2, "{blocks:?}");
    match &blocks[0] {
        crate::acp::types::PromptInputBlock::Text { text } => {
            assert!(text.starts_with("<codeg-now>"), "{text}");
            assert!(text.ends_with(&format!("</codeg-now>\n\n[#{}] use this screenshot", second.id)), "{text}");
        }
        other => panic!("the text leads: {other:?}"),
    }
    assert!(matches!(&blocks[1], crate::acp::types::PromptInputBlock::Image { .. }));
    assert_eq!(second.data.as_ref().unwrap()["merged"], true);
}

/// The turn ends while a message is being handed to it. Claimed before the
/// hand-over, the message is settled with the turn when the agent took it,
/// and goes back to the queue — once, unread — when it did not.
#[tokio::test]
async fn a_message_claimed_by_a_turn_that_ends_during_the_hand_over_is_settled_once() {
    // (taken by the agent, how the turn ended)
    for (taken, stop) in [(true, "end_turn"), (false, "end_turn"), (false, "rejected")] {
        let (engine, _tmp) = configured().await;
        let seg = open_segment(&engine).await;
        let batch = svc::create_batch(&engine.db.conn, engine.bot().await, seg, BatchKind::Delivery, None)
            .await
            .unwrap()
            .id;
        let first = engine.send_owner_message("first".into(), Vec::new(), None).await.unwrap();
        svc::move_owner_rows(
            &engine.db.conn,
            &[first.id],
            &[OwnerStatus::Queued],
            OwnerStatus::Delivered,
            Some(batch),
            Some(seg),
            svc::ReadMark::Read,
        )
        .await
        .unwrap();
        let mut rx = engine
            .manager
            .insert_test_connection_live("c", AgentType::ClaudeCode, None, EventEmitter::Noop)
            .await;
        {
            let state = engine.manager.get_state("c").await.unwrap();
            let mut s = state.write().await;
            s.native_steering_available = true;
            s.turn_in_flight = true;
            s.agent_info = Some(("codex-acp".into(), "2.5.0".into()));
        }
        engine.begin_turn_for_test("c", seg, batch, BatchKind::Delivery, false, false).await;
        engine.set_turn_owner_rows_for_test(vec![first.id]).await;
        let e = engine.clone();
        let handler = tokio::spawn(async move {
            match rx.recv().await {
                Some(ConnectionCommand::Steer { reply, .. }) => {
                    // The turn ends before the steer is answered.
                    e.feed_for_test("c", 1, turn_complete(stop)).await;
                    let _ = reply.send(if taken {
                        Ok(SteerOutcome::Injected)
                    } else {
                        Err(crate::acp::error::AcpError::NoActiveTurn)
                    });
                }
                _ => panic!("expected a steer"),
            }
        });
        let second = engine.send_owner_message("second".into(), Vec::new(), None).await.unwrap();
        handler.await.unwrap();
        assert!(!engine.turn_in_flight_for_test().await);
        let r2 = svc::get_row(&engine.db.conn, second.id).await.unwrap().unwrap();
        let queued = svc::queued_owner_rows(&engine.db.conn, engine.bot().await).await.unwrap();
        if taken {
            assert_eq!(r2.status, Some(OwnerStatus::Answered), "settled with the turn");
            assert_eq!(data_of(&r2)["merged"], true);
            assert!(queued.is_empty(), "not sent a second time");
        } else if stop == "rejected" {
            // The turn was interrupted meanwhile: the claim went down with
            // the turn's own message, and is sent again from the page like
            // it — not queued here as well, or the owner's own resend would
            // make two.
            assert_eq!(r2.status, Some(OwnerStatus::Interrupted));
            assert_eq!(data_of(&r2).get("merged"), None);
            assert!(queued.is_empty());
            let r1 = svc::get_row(&engine.db.conn, first.id).await.unwrap().unwrap();
            assert_eq!(r1.status, Some(OwnerStatus::Interrupted), "the turn's own message too");
            let copy = engine.resend(second.id).await.unwrap();
            assert_eq!(copy.status, Some(OwnerStatus::Queued));
            assert_eq!(
                svc::queued_owner_rows(&engine.db.conn, engine.bot().await).await.unwrap().len(),
                1,
                "exactly one copy"
            );
        } else {
            // The turn finished meanwhile: nothing of this message reached
            // the agent, so it simply goes next.
            assert_eq!(r2.status, Some(OwnerStatus::Queued), "waits for the next delivery");
            assert!(r2.read_at.is_none());
            assert_eq!(queued.len(), 1);
            assert_eq!(data_of(&r2).get("merged"), None);
        }
        let b = svc::get_batch(&engine.db.conn, batch).await.unwrap().unwrap();
        if stop == "rejected" {
            assert_eq!(b.status, BatchStatus::Interrupted);
        } else {
            assert_eq!(b.status, BatchStatus::Completed);
        }
    }
}

/// Settling a turn is serialized with deliveries: while one is being
/// delivered, the end of a turn waits; and while a turn is being settled
/// (its events put back), no delivery starts.
#[tokio::test]
async fn settling_a_turn_waits_for_the_delivery_in_flight() {
    let (engine, _tmp) = configured().await;
    let seg = open_segment(&engine).await;
    let (batch, event) = event_in_a_batch(&engine, seg, "dispatch:5:0:completed:turn").await;
    engine.begin_turn_for_test("c", seg, batch, BatchKind::Delivery, false, false).await;
    engine.send_owner_message("now".into(), Vec::new(), None).await.unwrap();
    let guard = engine.hold_pump_for_test().await;
    let e = engine.clone();
    let settling = tokio::spawn(async move {
        e.feed_for_test("c", 1, turn_complete("cancelled")).await;
    });
    for _ in 0..20 {
        tokio::task::yield_now().await;
    }
    tokio::time::sleep(std::time::Duration::from_millis(50)).await;
    assert!(engine.turn_in_flight_for_test().await, "waits for the delivery lock");
    assert!(
        svc::pending_events(&engine.db.conn, engine.bot().await).await.unwrap().is_empty(),
        "nothing put back yet"
    );
    drop(guard);
    settling.await.unwrap();
    assert!(!engine.turn_in_flight_for_test().await);
    let pending = svc::pending_events(&engine.db.conn, engine.bot().await).await.unwrap();
    assert_eq!(pending.iter().map(|e| e.id).collect::<Vec<_>>(), vec![event]);
}

// ── 1.4: assistants working with each other ─────────────────────────────────

use crate::db::entities::personal_agent_message::MessageState;
use crate::db::entities::personal_agent_thread::ThreadState;
use crate::db::service::personal_agent_message_service as msvc;

async fn say(engine: &Arc<PersonalAgentEngine>, args: serde_json::Value) -> super::tools::ToolOutcome {
    super::tools::call_for_test(engine, "bot_message", args).await
}

fn sent_id(out: &super::tools::ToolOutcome) -> i32 {
    assert!(out.ok, "{}", out.text);
    out.data["message_id"].as_i64().unwrap() as i32
}

async fn message(engine: &PersonalAgentEngine, id: i32) -> crate::db::entities::personal_agent_message::Model {
    msvc::get_message(&engine.db.conn, id).await.unwrap().unwrap()
}

async fn rows_of(engine: &PersonalAgentEngine, bot: i32, kind: TimelineKind) -> Vec<crate::db::entities::personal_agent_timeline::Model> {
    let (rows, _) = svc::page(&engine.db.conn, bot, None, 200).await.unwrap();
    rows.into_iter().filter(|r| r.kind == kind).collect()
}

/// A delivery of `engine` on `conn` carrying `owners` and `events`, on
/// record as running.
async fn turn_with(engine: &PersonalAgentEngine, seg: i32, conn: &str, owners: &[i32], events: &[i32]) -> i32 {
    let bot = engine.bot().await;
    let batch = svc::create_batch(&engine.db.conn, bot, seg, BatchKind::Delivery, None)
        .await
        .unwrap();
    svc::move_owner_rows(
        &engine.db.conn,
        owners,
        &[OwnerStatus::Queued],
        OwnerStatus::Delivered,
        Some(batch.id),
        Some(seg),
        svc::ReadMark::Read,
    )
    .await
    .unwrap();
    svc::mark_events_delivered(&engine.db.conn, events, batch.id).await.unwrap();
    engine
        .begin_turn_for_test(conn, seg, batch.id, BatchKind::Delivery, false, false)
        .await;
    batch.id
}

async fn pending_message_events(engine: &PersonalAgentEngine, bot: i32) -> Vec<crate::db::entities::personal_agent_event::Model> {
    svc::pending_events(&engine.db.conn, bot)
        .await
        .unwrap()
        .into_iter()
        .filter(|e| e.kind == msvc::MESSAGE_EVENT)
        .collect()
}

#[tokio::test]
async fn a_message_sent_in_a_turn_keeps_the_text_the_turn_wrote_before_it() {
    let (primary, _tmp) = configured().await;
    let w = worker_row(&primary, "Dev").await;
    let p = primary.bot().await;
    let seg = open_segment(&primary).await;
    let (mut rx, state) = live_connection(&primary, seg, "pa-1").await;
    primary
        .send_owner_message("give the login fix to Dev".into(), Vec::new(), None)
        .await
        .unwrap();
    primary.pump().await;
    let (_, token) = take_prompt(&mut rx);
    start_prompt(&state, Some(&token)).await;
    emit(
        &primary,
        &state,
        "pa-1",
        text("I'll hand the login fix to Dev."),
        true,
    )
    .await;
    emit(&primary, &state, "pa-1", tool("t1", "bot_message"), true).await;
    sent_id(
        &say(
            &primary,
            json!({ "to": w.to_string(), "text": "Fix the login bug." }),
        )
        .await,
    );
    // The sender's line says where the turn was: the step it sent from, and
    // the text it wrote before — which the reply's body will not keep.
    let out = rows_of(&primary, p, TimelineKind::Exchange).await;
    assert_eq!(out.len(), 1);
    let turn = data_of(&out[0])["turn"].clone();
    assert_eq!(turn["n"], 2, "{turn}");
    assert_eq!(turn["said"]["n"], 1, "{turn}");
    assert_eq!(
        turn["said"]["text"], "I'll hand the login fix to Dev.",
        "{turn}"
    );
    // The receiver's line is no turn's of its own.
    let inn = rows_of(&primary, w, TimelineKind::Exchange).await;
    assert!(data_of(&inn[0]).get("turn").is_none(), "{:?}", inn[0].data);
    // The body is what came after: the page draws the line before it.
    emit(&primary, &state, "pa-1", text("Dev has it."), true).await;
    emit(&primary, &state, "pa-1", turn_complete("end_turn"), true).await;
    let reply = reply_of(&primary, out[0].batch_id.expect("sent in the delivery")).await;
    assert_eq!(reply.body, "Dev has it.");
    assert_eq!(data_of(&reply)["last_text_n"], 3);
    // Answering a question the line once was keeps where it stood.
    primary
        .refresh_lines(sent_id_of_line(&out[0]), "replied")
        .await;
    let again = rows_of(&primary, p, TimelineKind::Exchange).await;
    assert_eq!(data_of(&again[0])["state"], "replied");
    assert_eq!(data_of(&again[0])["turn"], turn);
    // Outside any turn, a message records no place.
    sent_id(
        &say(
            &primary,
            json!({ "to": w.to_string(), "text": "And the signup page." }),
        )
        .await,
    );
    let out = rows_of(&primary, p, TimelineKind::Exchange).await;
    let last = out.iter().max_by_key(|r| r.id).unwrap();
    assert!(data_of(last).get("turn").is_none(), "{:?}", last.data);
}

/// The message a line is of (`m<id>`).
fn sent_id_of_line(row: &crate::db::entities::personal_agent_timeline::Model) -> i32 {
    row.ref_id
        .as_deref()
        .and_then(|r| r.strip_prefix('m'))
        .and_then(|r| r.parse().ok())
        .expect("a line names its message")
}

#[tokio::test]
async fn a_message_wakes_its_receiver_and_its_answer_closes_the_wait() {
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    let worker = host.engine_for(Some(w)).await.unwrap();
    let p = primary.bot().await;
    let id = sent_id(&say(&primary, json!({ "to": w.to_string(), "text": "Fix the cold-start white screen." })).await);
    let m = message(&primary, id).await;
    assert_eq!(m.state, MessageState::Queued);
    assert_eq!(m.thread_id, Some(id), "a new request starts its thread");
    assert!(m.wants_reply);
    assert_eq!((m.from_bot_id, m.to_bot_id), (p, w));
    assert_eq!(m.origin_bot_id, Some(p), "nobody started it: it starts at the sender");
    // The receiver has one thing to wake for.
    let queued = pending_message_events(&primary, w).await;
    assert_eq!(queued.len(), 1);
    assert!(queued[0].wake);
    assert_eq!(queued[0].thread_id, Some(id));
    // A line on each side, naming the other.
    let out = rows_of(&primary, p, TimelineKind::Exchange).await;
    assert_eq!(out.len(), 1);
    assert_eq!(data_of(&out[0])["direction"], "out");
    assert_eq!(data_of(&out[0])["peer"]["id"], w);
    let inn = rows_of(&primary, w, TimelineKind::Exchange).await;
    assert_eq!(inn.len(), 1);
    assert_eq!(data_of(&inn[0])["direction"], "in");
    assert_eq!(data_of(&inn[0])["peer"]["id"], p);
    assert_eq!(inn[0].event_id, Some(queued[0].id));
    // The sender waits for the answer.
    let waiting = svc::list_items(&primary.db.conn, p, &[ItemStatus::Waiting], 10).await.unwrap();
    assert_eq!(waiting.len(), 1);
    assert_eq!(waiting[0].kind, ItemKind::Message);

    // The answer goes back to whoever wrote, on the same thread.
    let out = say(&worker, json!({ "reply_to": format!("m{id}"), "text": "Fixed: PR #12." })).await;
    assert!(out.text.contains("to the primary assistant"), "an unnamed primary is called by its role: {}", out.text);
    let back = sent_id(&out);
    let answer = message(&primary, back).await;
    assert_eq!((answer.from_bot_id, answer.to_bot_id), (w, p));
    assert_eq!(answer.thread_id, Some(id));
    assert!(!answer.wants_reply, "an answer wants none unless it says so");
    assert_eq!(message(&primary, id).await.state, MessageState::Replied);
    let item = svc::get_item(&primary.db.conn, waiting[0].id).await.unwrap().unwrap();
    assert_eq!(item.status, ItemStatus::Done, "the wait is over");
    assert_eq!(pending_message_events(&primary, p).await.len(), 1, "the answer wakes the sender");
    assert!(
        svc::list_items(&worker.db.conn, w, &[ItemStatus::Waiting], 10).await.unwrap().is_empty(),
        "an answer that wants none leaves the replier nothing to wait for"
    );
}

#[tokio::test]
async fn a_delivery_carries_a_message_as_the_other_assistants_words() {
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    let worker = host.engine_for(Some(w)).await.unwrap();
    let id = sent_id(
        &say(&primary, json!({ "to": "Dev", "text": "FYI: the release is Friday.", "wants_reply": false })).await,
    );
    let seg = open_segment(&worker).await;
    let (mut rx, state) = live_connection(&worker, seg, "w-1").await;
    worker.pump().await;
    let (prompt, token) = take_prompt(&mut rx);
    for part in [
        format!("<codeg-message id=\"m{id}\" from=\""),
        "role=\"primary\"".to_string(),
        format!("thread=\"t{id}\""),
        "wants-reply=\"no\"".to_string(),
        "FYI: the release is Friday.</codeg-message>".to_string(),
        "not the owner's".to_string(),
    ] {
        assert!(prompt.contains(&part), "{part} in {prompt}");
    }
    assert!(!prompt.contains("<codeg-events>"), "a message is not news of work");
    let m = message(&worker, id).await;
    assert_eq!(m.state, MessageState::Delivered);
    let batch = svc::get_batch(&worker.db.conn, m.delivered_batch_id.unwrap()).await.unwrap().unwrap();
    assert_eq!(
        batch.trigger,
        Some(crate::db::entities::personal_agent_batch::BatchTrigger::Message)
    );
    for line in msvc::lines_of_message(&worker.db.conn, id).await.unwrap() {
        assert_eq!(data_of(&line)["state"], "delivered");
    }
    start_prompt(&state, Some(&token)).await;
    emit(&worker, &state, "w-1", text("Noted."), true).await;
    emit(&worker, &state, "w-1", turn_complete("end_turn"), true).await;
    assert_eq!(message(&worker, id).await.state, MessageState::Closed, "it wanted no answer");
}

