#[tokio::test]
async fn a_hand_over_and_a_round_opening_take_turns_on_the_route() {
    super::options::test_support::install(AgentType::ClaudeCode);
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    let worker = host.engine_for(Some(w)).await.unwrap();
    let d = session_dispatch(&worker, DispatchState::Running, "c-race").await;
    worker.track_conn("c-race", d).await;
    // A route change in progress: a round opening waits for it.
    let held = super::dispatch::ROUTES.lock().await;
    let opening = tokio::spawn({
        let worker = worker.clone();
        async move { worker.open_round("c-race", d).await }
    });
    for _ in 0..20 {
        tokio::task::yield_now().await;
    }
    assert!(
        worker.state.lock().await.dispatch_conns.get("c-race").is_some_and(|c| c.round_since.is_none()),
        "no round is registered while the route is changing hands"
    );
    // And a hand-over waits too: its owner and its route move together.
    let deleting = tokio::spawn({
        let (primary, existing) = (primary.clone(), host.existing_worker(w).await);
        async move {
            primary
                .delete_bot(w, &BotDeleteOptions { hand_over: true, ..Default::default() }, existing)
                .await
        }
    });
    for _ in 0..20 {
        tokio::task::yield_now().await;
    }
    assert_eq!(dispatch_state(&primary, d).await.bot_id, Some(w), "not handed over while the route is held");
    drop(held);
    opening.await.unwrap();
    deleting.await.unwrap().unwrap();
    let route = primary.state.lock().await.dispatch_conns.get("c-race").copied();
    assert!(route.is_some_and(|c| c.round_since.is_some()), "the primary routes it with its round open: {route:?}");
    assert!(!worker.owns_connection("c-race").await);
}

/// Antigravity tells a dead executor (a spent quota, a refused location) as
/// its whole reply and ends `end_turn`; codeg takes those words out of the
/// reply and marks the record `echoed_in_reply`. The dispatch's round failed,
/// in those words — not a success with an empty excerpt. A record the reply
/// did not carry leaves a round that ended well a success.
#[tokio::test]
async fn a_round_the_agent_told_failed_as_its_reply_fails_the_dispatch() {
    let (engine, _tmp) = ready().await;
    let failure = |echoed: bool| AcpEvent::SessionFailure {
        record: crate::acp::types::SessionFailureRecord {
            id: "antigravity:s1:1".into(),
            revision: 1,
            category: "quota".into(),
            severity: "error".into(),
            title: "You have exhausted your quota.".into(),
            details: None,
            actions: Vec::new(),
            resolved: false,
            echoed_in_reply: echoed,
        },
    };
    let event = |conn: &str, seq: u64, payload: AcpEvent| crate::acp::types::EventEnvelope {
        seq,
        connection_id: conn.into(),
        payload,
    };

    let told = session_dispatch(&engine, DispatchState::Running, "c-told").await;
    engine.track_conn("c-told", told).await;
    engine.open_round("c-told", told).await;
    engine.on_event(&event("c-told", 1, failure(true))).await;
    engine.on_event(&event("c-told", 2, turn_complete("end_turn"))).await;
    let d = dispatch_state(&engine, told).await;
    assert_eq!(d.state, DispatchState::Failed);
    assert_eq!(d.error.as_deref(), Some("You have exhausted your quota."));

    let fine = session_dispatch(&engine, DispatchState::Running, "c-fine").await;
    engine.track_conn("c-fine", fine).await;
    engine.open_round("c-fine", fine).await;
    engine.on_event(&event("c-fine", 1, failure(false))).await;
    engine.on_event(&event("c-fine", 2, turn_complete("end_turn"))).await;
    assert_eq!(dispatch_state(&engine, fine).await.state, DispatchState::Completed);

    // A failure a round told that nothing settled is not the next round's.
    let again = session_dispatch(&engine, DispatchState::Running, "c-again").await;
    engine.track_conn("c-again", again).await;
    engine.open_round("c-again", again).await;
    engine.on_event(&event("c-again", 1, failure(true))).await;
    engine.open_round("c-again", again).await;
    engine.on_event(&event("c-again", 2, turn_complete("end_turn"))).await;
    assert_eq!(dispatch_state(&engine, again).await.state, DispatchState::Completed);
}

/// A round's told failure goes with its route: the worker deleted with its
