#[tokio::test]
async fn a_due_reminder_shows_its_card_once_and_the_assistant_hears_of_it() {
    let (engine, _tmp) = configured().await;
    let out = call(&engine, "item_update", json!({ "kind": "reminder", "summary": "Stretch", "due": "2m" })).await;
    let id = out.data["item_id"].as_i64().unwrap() as i32;
    let now = super::clock::now();
    // Not yet.
    engine.fire_due_at(now).await;
    assert!(reminder_rows(&engine, id).await.is_empty());
    let at = now + chrono::Duration::minutes(3);
    engine.fire_due_at(at).await;
    engine.fire_due_at(at + chrono::Duration::seconds(15)).await;
    let rows = reminder_rows(&engine, id).await;
    assert_eq!(rows.len(), 1, "once");
    let card = data_of(&rows[0]);
    assert_eq!(card["state"], "open");
    assert_eq!(card["at_due"], "notify");
    assert_eq!(card["late_secs"], 0, "on time");
    assert_eq!(card["summary"], "Stretch");
    assert!(rows[0].body.starts_with(&format!("Reminder #{id}: Stretch")), "{}", rows[0].body);
    let item = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap();
    assert_eq!(item.fired_at, Some(at));
    assert_eq!(item.waits_for, Some(WaitsFor::Owner));
    // The assistant is not woken; it reads that the owner was reminded.
    let notes = item_notes(&engine).await;
    assert_eq!(notes.len(), 1);
    assert!(!notes[0].wake);
    assert!(notes[0].summary.contains(&format!("Reminder #{id} \"Stretch\" was shown to the owner")), "{}", notes[0].summary);

    // [15 minutes later]: the card says until when, the matter moves, and
    // it comes again then.
    let notice = notice_of_row(&rows[0]);
    let row = engine.act_on_notice(notice, "snooze:15m").await.unwrap();
    let data = row.data.clone().unwrap();
    assert_eq!(data["state"], "snoozed");
    assert!(data["until"].is_string());
    assert!(engine.act_on_notice(notice, "done").await.is_err(), "answered once");
    let item = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap();
    let until = item.due_at.unwrap();
    assert!(until > super::clock::now() + chrono::Duration::minutes(14));
    assert_eq!(item.fired_at, None);
    assert_eq!(item.status, ItemStatus::Open);
    assert!(item_notes(&engine).await.iter().any(|n| n.summary.contains(&format!("The owner put #{id} \"Stretch\" off until"))));
    engine.fire_due_at(until + chrono::Duration::seconds(1)).await;
    let rows = reminder_rows(&engine, id).await;
    assert_eq!(rows.len(), 2, "it comes again");
    // [Done]: the matter is done, the card says so.
    let row = engine.act_on_notice(notice_of_row(&rows[1]), "done").await.unwrap();
    assert_eq!(row.data.unwrap()["state"], "done");
    let item = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap();
    assert_eq!(item.status, ItemStatus::Done);
    engine.fire_due_at(until + chrono::Duration::hours(1)).await;
    assert_eq!(reminder_rows(&engine, id).await.len(), 2, "a done matter fires no more");
}

#[tokio::test]
async fn a_missed_reminder_comes_once_late_and_a_repeating_one_goes_on_from_its_latest_time() {
    let (engine, _tmp) = configured().await;
    let bot = engine.bot().await;
    let tz = engine.owner_tz().await;
    // Due at 09:00 three days ago, every day; codeg was not running since.
    let (first_text, first) = local_day(&engine, -3, "09:00").await;
    let rule = super::due::parse_repeat(
        &json!({ "every": "daily" }),
        chrono::NaiveDateTime::parse_from_str(&first_text, "%Y-%m-%d %H:%M").unwrap(),
    )
    .unwrap();
    let item = svc::create_item_timed(
        &engine.db.conn,
        bot,
        ItemKind::Reminder,
        None,
        ItemStatus::Open,
        Some(WaitsFor::Time),
        "Take the pills".into(),
        None,
        None,
        svc::ItemTime {
            due_at: Some(first),
            repeat: Some(serde_json::to_string(&rule).unwrap()),
            at_due: Some("notify".into()),
            ..Default::default()
        },
    )
    .await
    .unwrap();
    let (_, today_nine) = local_day(&engine, 0, "09:00").await;
    let back = today_nine + chrono::Duration::hours(1);
    engine.fire_due_at(back).await;
    let rows = reminder_rows(&engine, item.id).await;
    assert_eq!(rows.len(), 1, "once, not once per day missed");
    let card = data_of(&rows[0]);
    assert_eq!(card["missed"], 3);
    assert_eq!(card["late_secs"], 3600, "late from today's time");
    assert!(rows[0].body.contains("1 h late"), "{}", rows[0].body);
    let item = svc::get_item(&engine.db.conn, item.id).await.unwrap().unwrap();
    assert_eq!(item.due_at, Some(today_nine));
    engine.fire_due_at(back + chrono::Duration::minutes(30)).await;
    assert_eq!(reminder_rows(&engine, item.id).await.len(), 1);

    // Tomorrow's time comes with today's card still open: a new card, the
    // old one expired.
    let (_, tomorrow_nine) = local_day(&engine, 1, "09:00").await;
    engine.fire_due_at(tomorrow_nine + chrono::Duration::seconds(5)).await;
    let rows = reminder_rows(&engine, item.id).await;
    assert_eq!(rows.len(), 2);
    assert_eq!(data_of(&rows[0])["state"], "expired");
    assert_eq!(data_of(&rows[1])["state"], "open");
    assert_eq!(data_of(&rows[1])["late_secs"], 0);

    // Done on a repeating matter: done for this time, the next is set.
    let done = engine.settle_item(item.id, "done", None).await.unwrap();
    assert_eq!(done.status, ItemStatus::Open);
    let next = done.due_at.unwrap();
    assert!(next > super::clock::now(), "the next time is ahead");
    assert_eq!(next.with_timezone(&tz).format("%H:%M").to_string(), "09:00");
    assert_eq!(done.fired_at, None);
    assert_eq!(data_of(&reminder_rows(&engine, item.id).await[1])["state"], "done");
    assert!(item_notes(&engine).await.iter().any(|n| n.summary.contains("done for this time")));
}

#[tokio::test]
async fn a_matter_the_assistant_is_to_do_wakes_it_with_what_to_do() {
    let (engine, _tmp) = configured().await;
    let out = call(
        &engine,
        "item_update",
        json!({ "kind": "followup", "summary": "Check the release CI", "due": "5m", "at_due": "act",
                "act_spec": { "what": "Look at the release pipeline and tell the owner",
                              "dispatch": { "mode": "chat", "title": "CI check", "prompt": "Read the CI" } } }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let id = out.data["item_id"].as_i64().unwrap() as i32;
    let at = super::clock::now() + chrono::Duration::minutes(6);
    engine.fire_due_at(at).await;
    let rows = reminder_rows(&engine, id).await;
    assert_eq!(rows.len(), 1);
    assert_eq!(data_of(&rows[0])["state"], "woke");
    let events = svc::pending_events(&engine.db.conn, engine.bot().await).await.unwrap();
    let ev = events.iter().find(|e| e.kind == super::reminders::REMINDER_EVENT).expect("a wake-up");
    assert!(ev.wake);
    assert_eq!(rows[0].event_id, Some(ev.id), "the card numbers it");
    let item = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap();
    assert_eq!(item.waits_for, Some(WaitsFor::Agent));

    let seg = open_segment(&engine).await;
    let (mut rx, _state) = live_connection(&engine, seg, "pa-111").await;
    engine.pump().await;
    let (prompt, _) = take_prompt(&mut rx);
    assert!(prompt.starts_with("<codeg-now>"), "{prompt}");
    assert!(prompt.contains("this turn: a matter came due that you are to do"), "{prompt}");
    for part in [
        format!("[#{}] It is time for #{id} \"Check the release CI\"", rows[0].id),
        "What you are to do: Look at the release pipeline and tell the owner.".to_string(),
        "\"title\":\"CI check\"".to_string(),
    ] {
        assert!(prompt.contains(&part), "{part} in {prompt}");
    }
    let batch = svc::running_batches(&engine.db.conn, engine.bot().await).await.unwrap();
    assert_eq!(batch[0].trigger, Some(crate::db::entities::personal_agent_batch::BatchTrigger::Reminder));
}

#[tokio::test]
async fn every_delivery_starts_with_the_owners_time_now() {
    let (engine, _tmp) = configured().await;
    let tz = engine.owner_tz().await;
    let seg = open_segment(&engine).await;
    let (mut rx, _state) = live_connection(&engine, seg, "pa-now").await;
    engine.send_owner_message("hi".into(), Vec::new(), None).await.unwrap();
    engine.pump().await;
    let (prompt, _) = take_prompt(&mut rx);
    let first = prompt.lines().next().unwrap();
    assert!(first.starts_with("<codeg-now>") && first.ends_with("</codeg-now>"), "{first}");
    assert!(first.contains(&super::due::zone_label(tz, super::clock::now())), "{first}");
    assert!(first.contains("the owner's last message before this turn: none yet"), "{first}");
    assert!(first.contains("this turn: the owner's message"), "{first}");
    let local = super::clock::now().with_timezone(&tz);
    assert!(first.contains(&local.format("%Y-%m-%d %a").to_string()), "{first}");
    // With an earlier message, it says when the owner last wrote.
    let (engine, _tmp2) = configured().await;
    let mut earlier = NewRow::new(TimelineKind::Owner, "earlier");
    earlier.status = Some(OwnerStatus::Answered);
    let earlier = svc::insert_row(&engine.db.conn, engine.bot().await, earlier).await.unwrap();
    let seg = open_segment(&engine).await;
    let (mut rx, _state) = live_connection(&engine, seg, "pa-now-2").await;
    engine.send_owner_message("again".into(), Vec::new(), None).await.unwrap();
    engine.pump().await;
    let (prompt, _) = take_prompt(&mut rx);
    let at = earlier.created_at.with_timezone(&engine.owner_tz().await).format("%H:%M").to_string();
    let line = prompt.lines().next().unwrap();
    assert!(!line.contains("none yet") && line.contains(&at), "{line}");
}

#[tokio::test]
async fn the_owner_puts_a_matter_off_or_aside_without_the_brain() {
    let (engine, _tmp) = configured().await;
    let tz = engine.owner_tz().await;
    let bot = engine.bot().await;
    let f = svc::create_item(&engine.db.conn, bot, ItemKind::Followup, None, ItemStatus::Open, None, "Reply to Ana".into(), None, None)
        .await
        .unwrap();
    // A matter with no time put off an hour becomes a reminder then.
    let before = super::clock::now();
    let i = engine.settle_item(f.id, "snooze", Some("1h")).await.unwrap();
    let due = i.due_at.unwrap();
    assert!(due >= before + chrono::Duration::minutes(59) && due <= super::clock::now() + chrono::Duration::hours(1));
    assert_eq!(i.at_due.as_deref(), Some("notify"));
    assert_eq!(i.waits_for, Some(WaitsFor::Time));
    // Tomorrow morning: 09:00, in the owner's zone.
    let i = engine.settle_item(f.id, "snooze", Some("tomorrow")).await.unwrap();
    assert_eq!(i.due_at.unwrap().with_timezone(&tz).format("%H:%M").to_string(), "09:00");
    // Garbage and the past are refused.
    assert!(engine.settle_item(f.id, "snooze", Some("whenever")).await.is_err());
    assert!(engine.settle_item(f.id, "snooze", Some("2020-01-01 09:00")).await.is_err());
    // Snooze without a time is "later" — refused for one set for later
    // (it would keep its time, saying otherwise).
    let e = engine.settle_item(f.id, "snooze", None).await.unwrap_err();
    assert_eq!(e.key, Some(super::refusal::keys::HAS_TIME));
    let i = matter_of(&engine, f.id).await;
    assert_eq!(i.waits_for, Some(WaitsFor::Time));
    let notes = item_notes(&engine).await;
    assert!(notes.iter().all(|n| !n.wake), "the brain is not woken for them");
    assert!(notes.iter().any(|n| n.summary.contains(&format!("The owner put #{} \"Reply to Ana\" off until", f.id))));
    // Fired and set aside: no longer due.
    engine.fire_due_at(i.due_at.unwrap() + chrono::Duration::minutes(1)).await;
    let i = engine.settle_item(f.id, "later", None).await.unwrap();
    assert_eq!(i.due_at, None, "a one-off that came due waits with no time");
    assert!(reminder_rows(&engine, f.id).await.iter().all(|r| data_of(r)["state"] != "open"));
}

#[tokio::test]
async fn handing_a_reminder_to_the_assistant_is_the_owners_message_quoting_it() {
    let (engine, _tmp) = configured().await;
    let out = call(&engine, "item_update", json!({ "kind": "reminder", "summary": "Renew the domain", "due": "1m" })).await;
    let id = out.data["item_id"].as_i64().unwrap() as i32;
    engine.fire_due_at(super::clock::now() + chrono::Duration::minutes(2)).await;
    let card = reminder_rows(&engine, id).await.remove(0);
    let notice = notice_of_row(&card);
    let row = engine
        .act_on_notice_with(notice, "hand_over", Some(format!("处理提醒 #{id}：Renew the domain")))
        .await
        .unwrap();
    assert_eq!(row.data.unwrap()["state"], "handed");
    let owner = svc::queued_owner_rows(&engine.db.conn, engine.bot().await).await.unwrap();
    assert_eq!(owner.len(), 1);
    assert_eq!(owner[0].body, format!("处理提醒 #{id}：Renew the domain"));
    assert_eq!(owner[0].reply_to, Some(card.id), "it quotes the card");
    let item = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap();
    assert_eq!(item.waits_for, Some(WaitsFor::Agent));
    assert!(engine.act_on_notice_with(notice, "hand_over", None).await.is_err(), "once");
    assert!(engine.act_on_notice(notice, "accept").await.is_err());
}

#[tokio::test]
async fn a_change_read_before_a_firing_does_not_undo_it() {
    let (engine, _tmp) = configured().await;
    let tz = engine.owner_tz().await;
    let out = call(&engine, "item_update", json!({ "kind": "reminder", "summary": "Pay rent", "due": "1m" })).await;
    let id = out.data["item_id"].as_i64().unwrap() as i32;
    // The brain's update read the matter before the clock fired it ...
    let stale = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap();
    let at = super::clock::now() + chrono::Duration::minutes(2);
    engine.fire_due_at(at).await;
    assert_eq!(reminder_rows(&engine, id).await.len(), 1);
    // ... and writes its change after: the firing stands.
    let time = super::reminders::time_from_args(
        &json!({ "act_spec": { "what": "Pay it from the joint account" } }),
        Some(&stale),
        tz,
        super::clock::now(),
        super::due::Mornings::default(),
    )
    .unwrap();
    svc::update_item(&engine.db.conn, id, svc::ItemWrite { time, ..Default::default() }).await.unwrap();
    let item = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap();
    assert_eq!(item.fired_at, Some(at), "not written back from the earlier read");
    engine.fire_due_at(at + chrono::Duration::seconds(15)).await;
    assert_eq!(reminder_rows(&engine, id).await.len(), 1, "it does not fire again");
    assert!(
        !svc::pending_events(&engine.db.conn, engine.bot().await)
            .await
            .unwrap()
            .iter()
            .any(|e| e.kind == super::reminders::REMINDER_EVENT),
        "nor wake the assistant for the same time"
    );
}

#[tokio::test]
async fn matters_that_fired_and_wait_for_the_owner_do_not_hold_up_the_rest() {
    let (engine, _tmp) = configured().await;
    let bot = engine.bot().await;
    let due = super::clock::now() + chrono::Duration::minutes(1);
    let make = |n: usize| {
        let db = engine.db.conn.clone();
        async move {
            svc::create_item_timed(
                &db,
                bot,
                ItemKind::Reminder,
                None,
                ItemStatus::Open,
                Some(WaitsFor::Time),
                format!("Reminder {n}"),
                None,
                None,
                svc::ItemTime {
                    due_at: Some(due),
                    at_due: Some("notify".into()),
                    fresh: true,
                    ..Default::default()
                },
            )
            .await
            .unwrap()
        }
    };
    for n in 0..205 {
        make(n).await;
    }
    let at = due + chrono::Duration::minutes(1);
    engine.fire_due_at(at).await;
    engine.fire_due_at(at + chrono::Duration::seconds(15)).await;
    // 205 fired, none waiting on the owner's answer blocks the others.
    let fired = svc::list_items(&engine.db.conn, bot, &[], 500)
        .await
        .unwrap()
        .into_iter()
        .filter(|i| i.fired_at.is_some())
        .count();
    assert_eq!(fired, 205);
    let late = make(999).await;
    engine.fire_due_at(at + chrono::Duration::seconds(30)).await;
    assert_eq!(reminder_rows(&engine, late.id).await.len(), 1, "a newer one still fires");
}

#[tokio::test]
async fn a_reminder_card_whose_matter_moved_on_closes_as_it_stands() {
    let (engine, _tmp) = configured().await;
    let out = call(&engine, "item_update", json!({ "kind": "reminder", "summary": "Book the hall", "due": "1m" })).await;
    let id = out.data["item_id"].as_i64().unwrap() as i32;
    engine.fire_due_at(super::clock::now() + chrono::Duration::minutes(2)).await;
    let card = reminder_rows(&engine, id).await.remove(0);
    let notice = notice_of_row(&card);
    // The matter was settled, the card not (an answer cut off before it
    // marked the card, say).
    svc::update_item(&engine.db.conn, id, svc::ItemWrite { status: Some(ItemStatus::Done), ..Default::default() })
        .await
        .unwrap();
    let row = engine.act_on_notice(notice, "snooze:1h").await.unwrap();
    assert_eq!(row.data.unwrap()["state"], "done", "it closes as the matter stands");
    assert!(engine.act_on_notice(notice, "done").await.is_err(), "and is answered");
    let item = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap();
    assert_eq!(item.status, ItemStatus::Done, "nothing ran again");
    assert_eq!(item.due_at, out.data["due_at"].as_str().map(|s| s.parse().unwrap()));
}

/// A daily matter due yesterday at 09:00, not fired yet.
async fn daily_since_yesterday(engine: &PersonalAgentEngine, summary: &str) -> crate::db::entities::personal_agent_item::Model {
    let (text, first) = local_day(engine, -1, "09:00").await;
    let rule = super::due::parse_repeat(
        &json!({ "every": "daily" }),
        chrono::NaiveDateTime::parse_from_str(&text, "%Y-%m-%d %H:%M").unwrap(),
    )
    .unwrap();
    svc::create_item_timed(
        &engine.db.conn,
        engine.bot().await,
        ItemKind::Reminder,
        None,
        ItemStatus::Open,
        Some(WaitsFor::Time),
        summary.into(),
        None,
        None,
        svc::ItemTime {
            due_at: Some(first),
            repeat: Some(serde_json::to_string(&rule).unwrap()),
            at_due: Some("notify".into()),
            act_spec: None,
            fresh: true,
        },
    )
    .await
    .unwrap()
}

#[tokio::test]
async fn a_time_worked_out_before_the_clock_moved_it_does_not_land() {
    let (engine, _tmp) = configured().await;
    let tz = engine.owner_tz().await;
    let item = daily_since_yesterday(&engine, "Log the weight").await;
    // Read by the brain's update and the owner's [Done] ...
    let stale = svc::get_item(&engine.db.conn, item.id).await.unwrap().unwrap();
    // ... then the clock catches up to today's time.
    let (_, today) = local_day(&engine, 0, "09:00").await;
    let at = today + chrono::Duration::hours(1);
    engine.fire_due_at(at).await;
    let fired = svc::get_item(&engine.db.conn, item.id).await.unwrap().unwrap();
    assert_eq!((fired.due_at, fired.fired_at), (Some(today), Some(at)));
    // An act_spec change worked out from the earlier read is refused ...
    let time = super::reminders::time_from_args(
        &json!({ "act_spec": { "what": "Ask how it went" } }),
        Some(&stale),
        tz,
        super::clock::now(),
        super::due::Mornings::default(),
    )
    .unwrap();
    let err = engine
        .write_item(&stale, svc::ItemWrite { time: time.clone(), ..Default::default() }, None, None)
        .await
        .unwrap_err();
    assert!(err.contains("changed meanwhile"), "{err}");
    // ... and even written unguarded, it leaves the clock's due time alone.
    svc::update_item(&engine.db.conn, item.id, svc::ItemWrite { time, ..Default::default() }).await.unwrap();
    let now = svc::get_item(&engine.db.conn, item.id).await.unwrap().unwrap();
    assert_eq!((now.due_at, now.fired_at), (Some(today), Some(at)), "today's time stays fired");
    // So is a [Done] worked out from it: it would make today's time again.
    let next = super::reminders::after_done(&stale, tz, super::clock::now()).unwrap();
    assert!(engine
        .write_item(&stale, svc::ItemWrite { time: Some(next), ..Default::default() }, Some(("done", None)), None)
        .await
        .is_err());
    engine.fire_due_at(at + chrono::Duration::seconds(15)).await;
    assert_eq!(reminder_rows(&engine, item.id).await.len(), 1, "today's time fired once");
}

#[tokio::test]
async fn done_on_a_repeating_reminder_moves_it_once_together_with_its_card() {
    let (engine, _tmp) = configured().await;
    let tz = engine.owner_tz().await;
    let item = daily_since_yesterday(&engine, "Water the fern").await;
    let (_, today) = local_day(&engine, 0, "09:00").await;
    engine.fire_due_at(today + chrono::Duration::minutes(1)).await;
    let card = reminder_rows(&engine, item.id).await.remove(0);
    let notice = notice_of_row(&card);
    let row = engine.act_on_notice(notice, "done").await.unwrap();
    assert_eq!(row.data.unwrap()["state"], "done");
    let after = svc::get_item(&engine.db.conn, item.id).await.unwrap().unwrap();
    let next = after.due_at.unwrap();
    assert_eq!(after.status, ItemStatus::Open);
    // Today's 09:00 was done: tomorrow's, whatever the time now.
    assert_eq!(next, local_day(&engine, 1, "09:00").await.1);
    assert_eq!(next.with_timezone(&tz).format("%H:%M").to_string(), "09:00");
    // The card closed with the change: a second press moves nothing.
    assert!(engine.act_on_notice(notice, "done").await.is_err());
    assert_eq!(svc::get_item(&engine.db.conn, item.id).await.unwrap().unwrap().due_at, Some(next));
    let notice_row = svc::get_notice(&engine.db.conn, notice).await.unwrap().unwrap();
    assert_eq!(notice_row.state, crate::db::entities::personal_agent_notice::NoticeState::Acted);
    assert_eq!(
        item_notes(&engine).await.iter().filter(|n| n.summary.contains("done for this time")).count(),
        1
    );
}

// ── 1.12: presence and the owner's hours ───────────────────────────────────

async fn set_pref(engine: &Arc<PersonalAgentEngine>, key: &str, value: serde_json::Value) {
    engine.apply_settings(&[change(&format!("prefs.{key}"), value)]).await.unwrap();
}

/// A record of the owner active `from`–`to` (`HH:MM`) on every one of the
/// `days` days before the hours' today: workdays at `work`, rest days at
/// `rest`.
async fn seed_hours(engine: &PersonalAgentEngine, days: i64, work: (u32, u32), rest: (u32, u32)) {
    let tz = engine.owner_tz().await;
    let today = super::presence::hours_day(super::clock::now(), tz);
    for back in 1..=days {
        let date = today - chrono::Duration::days(back);
        let (from, to) = if super::due::is_rest_day(date) { rest } else { work };
        for slot in from / 5..to / 5 {
            for _ in 0..5 {
                crate::db::service::personal_agent_activity_service::add_minute(
                    &engine.db.conn,
                    date,
                    slot,
                    super::clock::now(),
                )
                .await
                .unwrap();
            }
        }
    }
}

#[tokio::test]
async fn the_owners_zone_is_theirs_to_set_and_every_time_follows_it() {
    let (engine, _tmp) = configured().await;
    assert_eq!(engine.owner_tz().await, super::clock::system_tz(), "the system's to begin with");
    set_pref(&engine, "time_zone", json!("Pacific/Auckland")).await;
    let tz = engine.owner_tz().await;
    assert_eq!(tz.name(), "Pacific/Auckland");
    let line = engine.now_line(None, "the owner's message").await;
    assert!(line.contains("(Pacific/Auckland, UTC+"), "{line}");
    // A time written in the owner's hours is read in their zone.
    let (due, at) = local_day(&engine, 1, "15:00").await;
    let out = call(&engine, "item_update", json!({ "kind": "reminder", "summary": "Call", "due": due })).await;
    assert!(out.ok && out.text.contains("Pacific/Auckland"), "{}", out.text);
    let id = out.data["item_id"].as_i64().unwrap() as i32;
    assert_eq!(svc::get_item(&engine.db.conn, id).await.unwrap().unwrap().due_at, Some(at));
    // The brain is told, with the preferences.
    let block = crate::models::personal_agent_prefs::prefs_block(&engine.prefs().await, false);
    assert!(block.contains("the owner's time zone: Pacific/Auckland"), "{block}");
    // A zone codeg does not know is refused; `system` goes back.
    assert!(engine.apply_settings(&[change("prefs.time_zone", json!("Mars/Base"))]).await.is_err());
    set_pref(&engine, "time_zone", json!("system")).await;
    assert_eq!(engine.owner_tz().await, super::clock::system_tz());
}

#[tokio::test]
async fn a_new_zone_moves_a_repeating_matter_to_its_clock_time_there() {
    let (engine, _tmp) = configured().await;
    set_pref(&engine, "time_zone", json!("Asia/Shanghai")).await;
    // The clock's first look takes the zone as it is.
    engine.fire_due_at(super::clock::now()).await;
    let (first, _) = local_day(&engine, 2, "09:00").await;
    let daily = call(
        &engine,
        "item_update",
        json!({ "kind": "reminder", "summary": "Stand-up", "due": first, "repeat": { "every": "daily" } }),
    )
    .await;
    assert!(daily.ok, "{}", daily.text);
    let daily = daily.data["item_id"].as_i64().unwrap() as i32;
    let (put_off, _) = local_day(&engine, 2, "10:15").await;
    let snoozed = call(
        &engine,
        "item_update",
        json!({ "kind": "reminder", "summary": "Water", "due": first, "repeat": { "every": "daily" } }),
    )
    .await;
    let snoozed = snoozed.data["item_id"].as_i64().unwrap() as i32;
    let out = call(&engine, "item_update", json!({ "item_id": snoozed, "due": put_off })).await;
    assert!(out.ok, "{}", out.text);
    let once = call(&engine, "item_update", json!({ "kind": "reminder", "summary": "Dentist", "due": first })).await;
    let once = once.data["item_id"].as_i64().unwrap() as i32;
    // The owner puts a daily 09:00 one off to tomorrow morning — 09:00
    // too, by the clock: still a moment of their own. (Put off, never
    // sooner: it is due tomorrow at 09:00 itself.) "Tomorrow" as the
    // snooze reads it — in the small hours that is this morning, not
    // the calendar's next day.
    let (tz, mornings) = engine.owner_day().await;
    let tomorrow = super::due::morning(tz, super::clock::now(), mornings)
        .with_timezone(&tz)
        .format("%Y-%m-%d %H:%M")
        .to_string();
    let pills = call(
        &engine,
        "item_update",
        json!({ "kind": "reminder", "summary": "Pills", "due": tomorrow, "repeat": { "every": "daily" } }),
    )
    .await;
    let pills = pills.data["item_id"].as_i64().unwrap() as i32;
    engine.settle_item(pills, "snooze", Some("tomorrow")).await.unwrap();
    let before = |id| {
        let engine = engine.clone();
        async move { svc::get_item(&engine.db.conn, id).await.unwrap().unwrap().due_at.unwrap() }
    };
    let sh: chrono_tz::Tz = "Asia/Shanghai".parse().unwrap();
    assert_eq!(before(pills).await.with_timezone(&sh).format("%H:%M").to_string(), "09:00");
    let (snoozed_at, once_at, pills_at) = (before(snoozed).await, before(once).await, before(pills).await);

    let rule = super::due::Repeat::parse(
        svc::get_item(&engine.db.conn, daily).await.unwrap().unwrap().repeat.as_deref(),
    )
    .unwrap();
    assert_eq!(rule.zone.as_deref(), Some("Asia/Shanghai"), "the rule keeps the zone its time was set in");

    // codeg restarts — the engine has not seen a zone — and the owner's is
    // another: the rule's own zone tells.
    *engine.clock_zone.lock().unwrap() = None;
    set_pref(&engine, "time_zone", json!("Europe/Berlin")).await;
    engine.fire_due_at(super::clock::now()).await;
    let berlin: chrono_tz::Tz = "Europe/Berlin".parse().unwrap();
    let moved = before(daily).await;
    assert_eq!(moved.with_timezone(&berlin).format("%H:%M").to_string(), "09:00", "its clock time in the new zone");
    assert!(moved > super::clock::now());
    assert_eq!(before(snoozed).await, snoozed_at, "put off to a moment of its own: it keeps it");
    assert_eq!(before(once).await, once_at, "a one-off is a moment");
    assert_eq!(before(pills).await, pills_at, "put off by the owner, on the rule's clock time or not");
    // Once only: the next look leaves it be.
    engine.fire_due_at(super::clock::now()).await;
    assert_eq!(before(daily).await, moved);
    let rule = super::due::Repeat::parse(
        svc::get_item(&engine.db.conn, daily).await.unwrap().unwrap().repeat.as_deref(),
    )
    .unwrap();
    assert_eq!(rule.zone.as_deref(), Some("Europe/Berlin"));
    let rule = super::due::Repeat::parse(
        svc::get_item(&engine.db.conn, snoozed).await.unwrap().unwrap().repeat.as_deref(),
    )
    .unwrap();
    assert_eq!(rule.zone.as_deref(), Some("Europe/Berlin"), "the one put off is in the new zone from now on");

    // A rule from before rules kept their zone takes the zone the clock
    // last saw.
    let (first, _) = local_day(&engine, 3, "07:30").await;
    let legacy = call(
        &engine,
        "item_update",
        json!({ "kind": "reminder", "summary": "Legacy", "due": first, "repeat": { "every": "daily" } }),
    )
    .await;
    let legacy = legacy.data["item_id"].as_i64().unwrap() as i32;
    let mut rule = super::due::Repeat::parse(
        svc::get_item(&engine.db.conn, legacy).await.unwrap().unwrap().repeat.as_deref(),
    )
    .unwrap();
    rule.zone = None;
    let item = svc::get_item(&engine.db.conn, legacy).await.unwrap().unwrap();
    svc::update_item(
        &engine.db.conn,
        legacy,
        svc::ItemWrite {
            time: Some(svc::ItemTime { repeat: Some(serde_json::to_string(&rule).unwrap()), ..svc::ItemTime::of(&item) }),
            ..Default::default()
        },
    )
    .await
    .unwrap();
    set_pref(&engine, "time_zone", json!("Asia/Tokyo")).await;
    engine.fire_due_at(super::clock::now()).await;
    let tokyo: chrono_tz::Tz = "Asia/Tokyo".parse().unwrap();
    assert_eq!(before(legacy).await.with_timezone(&tokyo).format("%H:%M").to_string(), "07:30");
}

#[tokio::test]
async fn the_owner_present_and_their_hours_reach_the_brain() {
    let (engine, _tmp) = configured().await;
    let window = format!("test-{}", uuid::Uuid::new_v4());
    let state = super::presence::beat(
        &engine.db.conn,
        super::presence::Beat { window: window.clone(), focused: true, idle_ms: Some(0), typed_ms: None, viewing: None, viewing_conversation: None },
    )
    .await;
    assert!(state.present);
    let line = engine.now_line(None, "the owner's message").await;
    assert!(line.contains(" · the owner is in codeg now · "), "{line}");
    assert!(!line.contains("usual hours"), "not learned yet: {line}");

    // Learned: the line has today's hours, and tomorrow morning is when
    // the owner's day starts.
    seed_hours(&engine, 14, (10 * 60 + 30, 19 * 60), (11 * 60, 17 * 60)).await;
    let tz = engine.owner_tz().await;
    let now = super::clock::now();
    let today = super::presence::hours_day(now, tz);
    let line = engine.now_line(None, "the owner's message").await;
    let want = if super::due::is_rest_day(today) {
        "their usual hours on a rest day: 11:00–17:00"
    } else {
        "their usual hours on a workday: 10:30–19:00"
    };
    assert!(line.contains(want), "{line}");
    let mornings = super::due::Mornings {
        workday: chrono::NaiveTime::from_hms_opt(10, 30, 0).unwrap(),
        restday: chrono::NaiveTime::from_hms_opt(11, 0, 0).unwrap(),
    };
    let out = call(&engine, "item_update", json!({ "kind": "reminder", "summary": "Read", "due": "tomorrow" })).await;
    assert!(out.ok, "{}", out.text);
    let id = out.data["item_id"].as_i64().unwrap() as i32;
    let due = svc::get_item(&engine.db.conn, id).await.unwrap().unwrap().due_at.unwrap();
    assert_eq!(due, super::due::morning(tz, super::clock::now(), mornings));

    // With the record off, the hours are the defaults.
    set_pref(&engine, "presence", json!("off")).await;
    let line = engine.now_line(None, "the owner's message").await;
    assert!(!line.contains("usual hours"), "{line}");
    let profile = super::presence::profile(&engine.db).await;
    assert!(!profile.presence && !profile.hours.workday.learned);
    set_pref(&engine, "presence", json!("on")).await;
    let profile = super::presence::profile(&engine.db).await;
    assert!(profile.presence && profile.hours.workday.learned && profile.hours.workday.days >= 5);
    assert_eq!((profile.hours.workday.start, profile.hours.workday.end), (10 * 60 + 30, 19 * 60));
    assert_eq!(profile.time_zone, "system");
    assert!(profile.zones.contains(&"Asia/Shanghai") && profile.zones.contains(&profile.zone.as_str()));
    super::presence::beat(
        &engine.db.conn,
        super::presence::Beat { window, focused: false, idle_ms: Some(0), typed_ms: None, viewing: None, viewing_conversation: None },
    )
    .await;
}

#[tokio::test]
async fn a_present_minute_is_recorded_only_while_the_owner_keeps_a_record() {
    let (engine, _tmp) = configured().await;
    set_pref(&engine, "time_zone", json!("Asia/Shanghai")).await;
    let sh: chrono_tz::Tz = "Asia/Shanghai".parse().unwrap();
    let at = chrono::TimeZone::with_ymd_and_hms(&sh, 2026, 11, 11, 10, 7, 0).unwrap().with_timezone(&chrono::Utc);
    super::presence::record_minute(&engine.db.conn, at).await;
    super::presence::record_minute(&engine.db.conn, at + chrono::Duration::minutes(1)).await;
    let day = chrono::NaiveDate::from_ymd_opt(2026, 11, 11).unwrap();
    let rows = crate::db::service::personal_agent_activity_service::since(&engine.db.conn, day).await.unwrap();
    assert_eq!(rows, vec![(day, (10 * 60 + 5) / 5, 2)], "two minutes in the 10:05 slot of the owner's day");

    set_pref(&engine, "presence", json!("off")).await;
    super::presence::record_minute(&engine.db.conn, at + chrono::Duration::minutes(2)).await;
    let rows = crate::db::service::personal_agent_activity_service::since(&engine.db.conn, day).await.unwrap();
    assert_eq!(rows, vec![(day, 121, 2)], "off: nothing more is written");

    // Nothing is recorded before an assistant is set up.
    let (bare, _tmp2) = self::engine().await;
    super::presence::record_minute(&bare.db.conn, at).await;
    assert!(crate::db::service::personal_agent_activity_service::since(&bare.db.conn, day).await.unwrap().is_empty());
}

#[tokio::test]
async fn the_record_keeps_sixty_days() {
    let (engine, _tmp) = configured().await;
    let conn = &engine.db.conn;
    let today = chrono::NaiveDate::from_ymd_opt(2026, 11, 11).unwrap();
    for back in [0, 59, 60, 61] {
        crate::db::service::personal_agent_activity_service::add_minute(
            conn,
            today - chrono::Duration::days(back),
            100,
            super::clock::now(),
        )
        .await
        .unwrap();
    }
    crate::db::service::personal_agent_activity_service::prune(conn, today - chrono::Duration::days(super::presence::KEEP_DAYS))
        .await
        .unwrap();
    let days: Vec<_> = crate::db::service::personal_agent_activity_service::since(conn, today - chrono::Duration::days(100))
        .await
        .unwrap()
        .into_iter()
        .map(|r| r.0)
        .collect();
    assert_eq!(days, vec![today - chrono::Duration::days(60), today - chrono::Duration::days(59), today]);
}

// ── 1.13 reaching the owner ────────────────────────────────────────────────

use crate::db::service::personal_agent_service::NewNotice;
use crate::models::personal_agent_prefs::Level;

fn owner_away() -> super::presence::Attending {
    super::presence::Attending::default()
}

/// The owner at codeg, typing last at `typed` (never: `None`), its window
/// not in front.
fn owner_here(typed: Option<chrono::DateTime<chrono::Utc>>) -> super::presence::Attending {
    super::presence::Attending {
        present: true,
        last_typed: typed,
        window_focused: false,
        viewing: vec![],
        viewing_conversations: vec![],
    }
}

/// A piece of news from assistant `bot`, as a hook tells it.
fn news(bot: i32, key: &str, kind: &'static str, text: &str) -> super::reach::News {
    super::reach::News {
        key: key.into(),
        bot_id: bot,
        kind,
        what: super::reach::What::Done { text: text.into() },
        link: Some(super::reach::NotifyLink::Bot { bot_id: bot, row_id: None }),
        need: None,
    }
}

/// A host whose quiet hours never come, the owner at `att`.
async fn reaching(att: super::presence::Attending) -> (Arc<EngineHost>, i32, tempfile::TempDir) {
    let (host, w, tmp) = hosted().await;
    set_pref(&host.primary(), "quiet_hours", json!("none")).await;
    host.reach.set_attending(Some(att));
    (host, w, tmp)
}

/// B6: work that just failed is its assistant's to pick up first — in
/// "today" it is watched, not waiting on the owner, until the moment is
/// over; an interruption (codeg retries those) and the owner's own task are
/// not held.
#[tokio::test]
async fn work_that_just_failed_is_watched_before_it_waits_on_the_owner() {
    let (host, _w, tmp) = hosted().await;
    let engine = host.primary();
    let conn = &engine.db.conn;
    let id = session_dispatch(&engine, DispatchState::Running, "c-f").await;
    svc::update_dispatch(conn, id, None, DispatchWrite { state: Some(DispatchState::Failed), error: Some(Some("boom".into())), ..Default::default() })
        .await
        .unwrap();
    let view = today_now(&engine).await;
    assert!(!view.needs.iter().any(|r| r.dispatch_id == Some(id)), "{:?}", view.needs);
    let row = view.watching.iter().find(|r| r.dispatch_id == Some(id)).expect("watched");
    assert_eq!((row.kind, row.reason), ("failed", Some("looking")));
    age_failure(&engine, id).await;
    let view = today_now(&engine).await;
    assert!(!view.watching.iter().any(|r| r.dispatch_id == Some(id)));
    assert_eq!(view.needs.iter().find(|r| r.dispatch_id == Some(id)).map(|r| r.reason), Some(Some("failed")));
    // A board task of the assistant's that just failed: watched; the
    // owner's own: theirs at once.
    use sea_orm::Set;
    let coder = role_assistant(&engine, "Coder", true).await;
    let project = crate::db::test_helpers::seed_folder(&engine.db, &tmp.path().join("app").to_string_lossy()).await;
    let mine = board_task(&engine, project, "Mine", WorkTaskStatus::Failed, |t| t.settled_at = Set(Some(chrono::Utc::now()))).await;
    task_dispatch(&engine, coder, project, mine.id, "Mine", DispatchState::Failed).await;
    let owners = board_task(&engine, project, "Owner's", WorkTaskStatus::Failed, |t| t.settled_at = Set(Some(chrono::Utc::now()))).await;
    let view = today_now(&engine).await;
    assert_eq!(view.watching.iter().find(|r| r.task_id == Some(mine.id)).map(|r| r.reason), Some(Some("looking")));
    assert!(view.needs.iter().any(|r| r.task_id == Some(owners.id)));
    assert!(!view.needs.iter().any(|r| r.task_id == Some(mine.id)));
}

/// B6: the owner hears that work failed only if it is still news once its
/// assistant had its moment — or once the turn that took it is over, when
/// that is sooner; not when the assistant took it over meanwhile.
#[tokio::test]
async fn a_failure_reaches_the_owner_only_if_it_is_still_news_after_its_assistant_s_moment() {
    let (host, _w, _tmp) = reaching(owner_here(None)).await;
    let engine = host.primary();
    role_assistant(&engine, "Coder", true).await;
    let conn = &engine.db.conn;
    let me = engine.bot().await;
    // The one slot taken, so the work that takes a failure over stays
    // queued: started, it would fail on its own wherever its agent is not
    // installed (on CI) and be one more failure held, whenever that is.
    engine
        .save(PersonalAgentDraft {
            settings: Some(PersonalAgentSettings { dispatch_concurrency: 1, ..Default::default() }),
            ..Default::default()
        })
        .await
        .unwrap();
    session_dispatch(&engine, DispatchState::Running, "c-busy").await;
    let fail = |name: &'static str| {
        let engine = engine.clone();
        async move {
            let id = session_dispatch(&engine, DispatchState::Running, name).await;
            let d = svc::update_dispatch(&engine.db.conn, id, None, DispatchWrite {
                state: Some(DispatchState::Failed),
                error: Some(Some("boom".into())),
                bump_turns: true,
                ..Default::default()
            })
            .await
            .unwrap()
            .unwrap();
            engine.record_progress(&d, None, Some("boom".into()), "turn").await;
            id
        }
    };
    let now = super::clock::now();
    // Each failure is due its hold after the real moment it failed, not
    // after `now`: leave the rest of the test an hour to get there, or on a
    // loaded runner a failure made a second after `now` is not yet due here
    // and lingers on the later list.
    let later = now + chrono::Duration::seconds(super::dispatch::FAILED_HOLD_SECS + 3600);
    // Nobody picks it up: told once its time is up, not before.
    fail("c-1").await;
    assert_eq!(host.reach.later_count(), 1);
    host.reach_tick_at(now).await;
    assert!(host.reach.take_sent().is_empty(), "not yet");
    host.reach_tick_at(later).await;
    assert_eq!(host.reach.take_sent().len(), 1);
    // Taken over meanwhile: not told.
    let second = fail("c-2").await;
    let out = call_tool(&engine, "dispatch", json!({ "mode": "chat", "title": "Again", "prompt": "p", "replaces": second })).await;
    assert!(out.ok, "{}", out.text);
    host.reach_tick_at(later).await;
    assert!(host.reach.take_sent().is_empty(), "taken over: no news");
    // The turn that took it is over: decided then, not at its time.
    let third = fail("c-3").await;
    let event = svc::pending_events(conn, me)
        .await
        .unwrap()
        .into_iter()
        .rev()
        .find(|e| e.payload.as_deref().is_some_and(|p| p.contains(&format!("\"dispatch_id\":{third}"))))
        .expect("its event");
    host.turn_over(&[event.id]);
    host.reach_tick_at(super::clock::now()).await;
    assert_eq!(host.reach.take_sent().len(), 1);
    assert_eq!(host.reach.later_count(), 0);
    // Picked up — a follow-up's claim, not known to have gone out — when
    // its time comes: asked again later; fallen back to failed, told.
    let fifth = fail("c-5").await;
    svc::update_dispatch(conn, fifth, None, DispatchWrite { state: Some(DispatchState::Running), ..Default::default() })
        .await
        .unwrap();
    host.reach_tick_at(later).await;
    assert!(host.reach.take_sent().is_empty());
    assert_eq!(host.reach.later_count(), 1, "held on");
    svc::update_dispatch(conn, fifth, None, DispatchWrite { state: Some(DispatchState::Failed), ..Default::default() })
        .await
        .unwrap();
    host.reach_tick_at(later + chrono::Duration::seconds(60)).await;
    assert_eq!(host.reach.take_sent().len(), 1, "fell back: told");
    // Held on for when the owner is back, and taken over before that: the
    // same check, not told.
    host.reach.set_attending(Some(owner_away()));
    let fourth = fail("c-4").await;
    host.reach_tick_at(later).await;
    assert_eq!(host.reach.held_counts().1, 1, "waits for the owner");
    let out = call_tool(&engine, "dispatch", json!({ "mode": "chat", "title": "Fourth again", "prompt": "p", "replaces": fourth })).await;
    assert!(out.ok, "{}", out.text);
    host.reach.set_attending(Some(owner_here(None)));
    host.reach_tick_at(later).await;
    assert!(host.reach.take_sent().is_empty(), "taken over while it waited");
}

/// B6: a restart writes the card of a failure codeg went down before
/// telling — once; a board run that failed again between two looks is
/// news of its own.
#[tokio::test]
async fn a_failure_is_in_the_conversation_once_after_a_restart_and_a_new_run_s_failure_is_its_own() {
    use sea_orm::Set;
    let (host, _w, tmp) = hosted().await;
    let engine = host.primary();
    let conn = &engine.db.conn;
    let id = session_dispatch(&engine, DispatchState::Failed, "c-b").await;
    assert!(svc::latest_result_row(conn, id).await.unwrap().is_none());
    engine.boot_failures().await;
    engine.boot_failures().await;
    let cards: Vec<_> = svc::result_rows_of_dispatch(conn, id).await.unwrap();
    assert_eq!(cards.len(), 1, "once");
    assert_eq!(data_of(&cards[0])["state"], "failed");

    let coder = role_assistant(&engine, "Coder", true).await;
    let project = crate::db::test_helpers::seed_folder(&engine.db, &tmp.path().join("app").to_string_lossy()).await;
    let task = board_task(&engine, project, "Flaky", WorkTaskStatus::Failed, |t| t.run_seq = Set(1)).await;
    let d = task_dispatch(&engine, coder, project, task.id, "Flaky", DispatchState::Failed).await;
    // Run 1's failure, told.
    engine.record_progress(&d, None, Some("flaky".into()), "task").await;
    engine.poll_task_dispatches().await;
    assert_eq!(svc::result_rows_of_dispatch(conn, d.id).await.unwrap().len(), 1, "nothing new in run 1");
    let mut am: crate::db::entities::work_task::ActiveModel =
        crate::db::service::work_task_service::get_model(conn, task.id).await.unwrap().into();
    am.run_seq = Set(2);
    sea_orm::ActiveModelTrait::update(am, conn).await.unwrap();
    engine.poll_task_dispatches().await;
    let cards = svc::result_rows_of_dispatch(conn, d.id).await.unwrap();
    assert_eq!(cards.len(), 2, "run 2's own card");
    assert_eq!(data_of(cards.last().unwrap())["run"], 2);
    assert!(dispatch_state(&engine, d.id).await.finished_at.unwrap() >= cards[0].created_at, "the dispatch says run 2's end");
    engine.poll_task_dispatches().await;
    assert_eq!(svc::result_rows_of_dispatch(conn, d.id).await.unwrap().len(), 2, "told once");
    // Failed with no news at all (codeg went down before it): told on the
    // next look, once.
    let lost_task = board_task(&engine, project, "Lost", WorkTaskStatus::Failed, |t| t.run_seq = Set(3)).await;
    let lost = task_dispatch(&engine, coder, project, lost_task.id, "Lost", DispatchState::Failed).await;
    engine.poll_task_dispatches().await;
    engine.poll_task_dispatches().await;
    let cards = svc::result_rows_of_dispatch(conn, lost.id).await.unwrap();
    assert_eq!(cards.len(), 1);
    assert_eq!(data_of(&cards[0])["run"], 3);
}

#[tokio::test]
async fn a_reminder_reaches_the_owner_once_under_the_assistants_name_saying_why() {
    let (host, _w, _tmp) = reaching(owner_away()).await;
    let engine = host.primary();
    let out = call(&engine, "item_update", json!({ "kind": "reminder", "summary": "Stretch", "due": "2m" })).await;
    let id = out.data["item_id"].as_i64().unwrap() as i32;
    let at = super::clock::now() + chrono::Duration::minutes(3);
    engine.fire_due_at(at).await;
    engine.fire_due_at(at + chrono::Duration::seconds(15)).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1, "once: {sent:?}");
    let n = &sent[0];
    let row = svc::get_bot(&host.db.conn, engine.bot().await).await.unwrap().unwrap();
    let name = if row.name.trim().is_empty() { "Personal agent".to_string() } else { row.name.clone() };
    assert_eq!(n.title, name);
    assert_eq!((n.level, n.attention, n.mode), (Level::Urgent, true, super::reach::Mode::System));
    assert!(
        n.body.starts_with("Reminder: Stretch\nYou asked to be reminded at "),
        "the last line says why: {}",
        n.body
    );
    let card = reminder_rows(&engine, id).await[0].id;
    assert_eq!(
        n.link,
        Some(super::reach::NotifyLink::Bot { bot_id: row.id, row_id: Some(card) })
    );
    assert_eq!(n.hidden_body, "Open codeg to see it");
}

#[tokio::test]
async fn what_waits_on_the_owner_is_told_as_it_comes_and_only_once() {
    let (host, w, _tmp) = reaching(owner_here(None)).await;
    let worker = svc::get_bot(&host.db.conn, w).await.unwrap().unwrap();
    let mut row = NewRow::new(TimelineKind::Notice, "Did the comment go out on PR #7?");
    row.data = Some(json!({ "notice": "uncertain", "state": "open" }));
    let (_, card) = svc::create_notice_with_row(
        &host.db.conn,
        w,
        NewNotice {
            kind: NoticeKind::Uncertain,
            subject_key: None,
            level: NoticeLevel::Normal,
            batch_id: None,
            payload: json!({}),
        },
        row,
    )
    .await
    .unwrap();
    let (_, needs) = host.live_with_needs(&worker).await;
    host.reach_needs(&worker, &needs).await;
    host.reach_needs(&worker, &needs).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1, "{sent:?}");
    assert_eq!(sent[0].title, "Dev");
    assert_eq!(sent[0].level, Level::Normal);
    assert_eq!(
        sent[0].body,
        "Waiting for you: Did the comment go out on PR #7?\nIt needs you to decide what happens next."
    );
    assert_eq!(sent[0].link, Some(super::reach::NotifyLink::Bot { bot_id: w, row_id: Some(card.id) }));
    // Gone and back is new.
    host.reach_needs(&worker, &[]).await;
    host.reach_needs(&worker, &needs).await;
    assert!(host.reach.take_sent().is_empty(), "the same card is told once");
}

#[tokio::test]
async fn normal_news_waits_while_the_owner_types_and_while_they_are_away() {
    let now = super::clock::now();
    let (host, w, _tmp) = reaching(owner_here(Some(now))).await;
    host.tell_at(news(w, "done:1", "done", "Fix login"), now).await;
    assert!(host.reach.take_sent().is_empty(), "they are typing");
    assert_eq!(host.reach.held_counts(), (1, 0, 0));
    // Still typing a minute on; three minutes after they stopped, it goes.
    host.reach.set_attending(Some(owner_here(Some(now + chrono::Duration::minutes(1)))));
    host.reach_tick_at(now + chrono::Duration::minutes(2)).await;
    assert!(host.reach.take_sent().is_empty());
    host.reach_tick_at(now + chrono::Duration::minutes(4)).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1);
    assert_eq!(sent[0].body, "Done: Fix login\nIt dispatched this work for you.");

    // Away: held until they are back, then merged.
    host.reach.set_attending(Some(owner_away()));
    host.tell_at(news(w, "done:2", "done", "Bump deps"), now).await;
    host.tell_at(news(w, "done:3", "done", "Write docs"), now).await;
    host.reach_tick_at(now + chrono::Duration::minutes(5)).await;
    assert!(host.reach.take_sent().is_empty());
    assert_eq!(host.reach.held_counts(), (0, 2, 0));
    host.reach.set_attending(Some(owner_here(None)));
    host.reach_tick_at(now + chrono::Duration::minutes(30)).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1, "merged");
    assert_eq!(sent[0].title, "Dev");
    assert_eq!(
        sent[0].body,
        "While you were away — 2 things\n· Done: Bump deps\n· Done: Write docs"
    );
    // Urgent does not wait for anyone.
    host.reach.set_attending(Some(owner_here(Some(now))));
    host.tell_at(news(w, "approval:1", "approval", "rm -rf build"), now).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1);
    assert!(sent[0].attention);
}

#[tokio::test]
async fn quiet_hours_let_only_the_owners_reminders_through_until_they_end() {
    let (host, w, _tmp) = reaching(owner_here(None)).await;
    let engine = host.primary();
    let tz = engine.owner_tz().await;
    let now = super::clock::now();
    let local = now.with_timezone(&tz);
    let from = (local - chrono::Duration::hours(1)).format("%H:%M").to_string();
    let to = (local + chrono::Duration::hours(1)).format("%H:%M").to_string();
    set_pref(&engine, "quiet_hours", json!("fixed")).await;
    set_pref(&engine, "quiet_from", json!(from)).await;
    set_pref(&engine, "quiet_to", json!(to)).await;
    host.tell_at(news(w, "approval:q", "approval", "push to main"), now).await;
    host.tell_at(news(w, "done:q", "done", "Fix login"), now).await;
    let mut reminder = news(w, "reminder:q", "reminder", "");
    reminder.what = super::reach::What::Reminder { text: "Stand-up".into(), at: "09:00".into() };
    host.tell_at(reminder, now).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1, "only the reminder: {sent:?}");
    assert!(sent[0].body.starts_with("Reminder: Stand-up"));
    host.reach_tick_at(now + chrono::Duration::minutes(10)).await;
    assert!(host.reach.take_sent().is_empty(), "still quiet");
    host.reach_tick_at(now + chrono::Duration::minutes(70)).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1);
    assert!(sent[0].body.contains("Waiting for your approval") || sent[0].body.contains("push to main"), "{}", sent[0].body);
    assert!(sent[0].body.starts_with("While you were away — 2 things"), "{}", sent[0].body);
}

#[tokio::test]
async fn muted_hidden_switched_off_and_looked_at_assistants_do_not_interrupt() {
    let (host, w, _tmp) = reaching(owner_here(None)).await;
    let now = super::clock::now();
    host.roster_act(w, crate::models::personal_agent_roster::RosterAct::Mute).await.unwrap();
    host.tell_at(news(w, "approval:m", "approval", "x"), now).await;
    let mut reminder = news(w, "reminder:m", "reminder", "");
    reminder.what = super::reach::What::Reminder { text: "Pills".into(), at: "21:00".into() };
    host.tell_at(reminder, now).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1, "a muted assistant still brings the owner's reminder");
    assert!(sent[0].body.starts_with("Reminder: Pills"));
    host.roster_act(w, crate::models::personal_agent_roster::RosterAct::Unmute).await.unwrap();
    host.roster_act(w, crate::models::personal_agent_roster::RosterAct::Notify { on: false }).await.unwrap();
    host.tell_at(news(w, "approval:n", "approval", "x"), now).await;
    host.roster_act(w, crate::models::personal_agent_roster::RosterAct::Notify { on: true }).await.unwrap();
    host.roster_act(w, crate::models::personal_agent_roster::RosterAct::Hide).await.unwrap();
    host.tell_at(news(w, "approval:h", "approval", "x"), now).await;
    host.roster_act(w, crate::models::personal_agent_roster::RosterAct::Show).await.unwrap();
    assert!(host.reach.take_sent().is_empty());
    // In front of them: no notification.
    host.reach.set_attending(Some(super::presence::Attending { viewing: vec![w], ..owner_here(None) }));
    host.tell_at(news(w, "approval:v", "approval", "x"), now).await;
    assert!(host.reach.take_sent().is_empty());
    // A window with the focus shows it on the page.
    host.reach.set_attending(Some(super::presence::Attending { window_focused: true, ..owner_here(None) }));
    host.tell_at(news(w, "approval:t", "approval", "x"), now).await;
    let sent = host.reach.take_sent();
    assert_eq!(sent.len(), 1);
    assert_eq!(sent[0].mode, super::reach::Mode::Toast);
    // Not proactive: only reminders.
    set_pref(&host.primary(), "proactive", json!("off")).await;
    host.reach.set_attending(Some(owner_here(None)));
    host.tell_at(news(w, "approval:p", "approval", "x"), now).await;
    assert!(host.reach.take_sent().is_empty());
}

