// ── 2.9: the menu bar and the dock ──────────────────────────────────────────

use super::menubar::{MenuBarSink, TrayView};

/// The menu bar as a test sees it: each view drawn.
#[derive(Default)]
struct TrayRecord(std::sync::Mutex<Vec<TrayView>>);

impl MenuBarSink for TrayRecord {
    fn show(&self, view: &TrayView) {
        self.0.lock().unwrap().push(view.clone());
    }
}

impl TrayRecord {
    fn last(&self) -> TrayView {
        self.0.lock().unwrap().last().cloned().unwrap_or_default()
    }

    /// The view drawn once `ok` holds of it (within 3 s), else the last.
    async fn once(&self, what: &str, ok: impl Fn(&TrayView) -> bool) -> TrayView {
        for _ in 0..60 {
            let v = self.last();
            if ok(&v) {
                return v;
            }
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
        }
        panic!("{what}: {:?}", self.last());
    }
}

#[tokio::test]
async fn the_menu_bar_shows_who_works_and_who_has_unread_and_its_switches_put_it_back() {
    let (host, w, _tmp) = hosted().await;
    host.live.set_enabled(true);
    let primary = host.primary().bot().await;
    let rec = Arc::new(TrayRecord::default());
    host.menubar_start(rec.clone()).await;
    let first = rec.last();
    assert!(first.menubar);
    assert_eq!((first.face, first.count, first.badge), (None, 0, 0));
    let mut listed: Vec<i32> = first.recent.iter().map(|r| r.id).collect();
    listed.sort();
    assert_eq!(listed, [primary, w]);
    assert!(first.recent.iter().any(|r| r.id == primary && r.primary));

    // It works: its face is shown; a push saying it rests takes it away.
    let row = svc::get_bot(&host.db.conn, w).await.unwrap().unwrap();
    let mut live = host.live_of(&row).await;
    live.work = WorkState::Busy;
    host.menubar_saw(&live);
    rec.once("its face", |v| v.face == Some(w)).await;
    host.touch(w);
    rec.once("at rest", |v| v.face.is_none()).await;

    // Unread: counted beside the icon and on the dock, marked in the menu.
    host.roster_act(w, RosterAct::MarkUnread).await.unwrap();
    let v = rec.once("one unread", |v| v.count == 1).await;
    assert_eq!(v.badge, 1);
    assert!(v.recent.iter().any(|r| r.id == w && r.unread));
    // Muted: still marked in the menu, counted nowhere.
    host.roster_act(w, RosterAct::Mute).await.unwrap();
    let v = rec.once("muted", |v| v.count == 0).await;
    assert_eq!(v.badge, 0);
    assert!(v.recent.iter().any(|r| r.id == w && r.unread));
    host.roster_act(w, RosterAct::Unmute).await.unwrap();
    rec.once("unmuted", |v| v.count == 1).await;

    // The switches: the menu bar as it was, the badge gone.
    let engine = host.primary();
    engine
        .apply_settings(&[change("prefs.menubar", json!("off"))])
        .await
        .unwrap();
    let v = rec.once("menu bar off", |v| !v.menubar).await;
    assert_eq!(
        v,
        TrayView {
            badge: 1,
            ..TrayView::default()
        }
    );
    engine
        .apply_settings(&[change("prefs.dock_badge", json!("off"))])
        .await
        .unwrap();
    rec.once("badge off", |v| v.badge == 0).await;
    engine
        .apply_settings(&[
            change("prefs.menubar", json!("on")),
            change("prefs.dock_badge", json!("on")),
        ])
        .await
        .unwrap();
    rec.once("both on", |v| v.menubar && v.badge == 1).await;

    // Hidden: not listed, not counted, its face never shown.
    host.roster_act(w, RosterAct::Hide).await.unwrap();
    let v = rec.once("hidden", |v| v.count == 0).await;
    assert!(v.recent.iter().all(|r| r.id != w));
    host.menubar_saw(&live);
    tokio::time::sleep(std::time::Duration::from_millis(400)).await;
    assert_eq!(rec.last().face, None, "a hidden one's face is not shown");

    // A face handed over again is drawn anew.
    let before = rec.last().pictures;
    host.menubar_pictures();
    rec.once("pictures", |v| v.pictures > before).await;
}

// ── 2.10: the time machine ──────────────────────────────────────────────────

/// A conversation in `folder` as parsed: the owner asks, the agent answers.
async fn parsed_session(
    engine: &PersonalAgentEngine,
    folder: i32,
    title: &str,
    asked: &str,
    answered: &str,
) -> (i32, crate::models::DbConversationDetail) {
    let conn = &engine.db.conn;
    let c = crate::db::service::conversation_service::create(
        conn,
        folder,
        AgentType::ClaudeCode,
        Some(title.into()),
        None,
    )
    .await
    .unwrap();
    let summary = crate::db::service::conversation_service::get_by_id(conn, c.id)
        .await
        .unwrap();
    let turn =
        |id: &str, role: &str, blocks: serde_json::Value| -> crate::models::message::MessageTurn {
            serde_json::from_value(
            json!({ "id": id, "role": role, "blocks": blocks, "timestamp": chrono::Utc::now() }),
        )
        .unwrap()
        };
    let detail = crate::models::DbConversationDetail {
        summary,
        turns: vec![
            turn("turn-0", "user", json!([{ "type": "text", "text": asked }])),
            turn(
                "turn-1",
                "assistant",
                json!([
                    { "type": "text", "text": "Let me look." },
                    { "type": "tool_use", "tool_name": "Bash", "tool_use_id": null, "input_preview": null },
                    { "type": "text", "text": answered }
                ]),
            ),
        ],
        session_stats: None,
        transcript_watermark: None,
        in_flight_user_turn_id: None,
        turns_offset: None,
        turns_total: None,
        assistant_turns_before_offset: None,
        user_turns_before_offset: None,
        prefix_hash: None,
        uncovered_prefix_max_ts: None,
    };
    (c.id, detail)
}

#[test]
fn the_time_machine_finds_what_was_said_and_done_and_leaves_out_what_the_owner_turned_off() {
    // A thread of its own with room: in a debug build the steps' poll keeps a
    // slot for every future it starts, more than a test thread's stack.
    std::thread::Builder::new()
        .stack_size(16 << 20)
        .spawn(|| {
            tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .unwrap()
                .block_on(time_machine_steps())
        })
        .unwrap()
        .join()
        .unwrap();
}

async fn time_machine_steps() {
    use super::history::{self, Makers};
    use crate::db::service::personal_agent_history_service as store;
    let (host, w, _tmp) = hosted().await;
    let engine = host.primary();
    let p = engine.bot().await;
    let conn = &host.db.conn;
    let folder = crate::db::test_helpers::seed_folder(&host.db, "/tmp/pa-history").await;

    // The owner asked on the timeline; the primary answered with a card.
    let asked = svc::insert_row(
        conn,
        p,
        NewRow::new(TimelineKind::Owner, "为什么把打包脚本改成 PowerShell 了？"),
    )
    .await
    .unwrap();
    let mut reply = NewRow::new(
        TimelineKind::Reply,
        "因为 bash 在 Windows 上要装 Git Bash。",
    );
    reply.data = Some(json!({ "state": "done" }));
    svc::insert_row(conn, p, reply).await.unwrap();
    // A reply still being written is not searched yet.
    let mut writing = NewRow::new(TimelineKind::Reply, "半句话 PowerShell");
    writing.data = Some(json!({ "state": "running" }));
    let writing = svc::insert_row(conn, p, writing).await.unwrap();
    // A message to the worker, a task on the board.
    sent_id(
        &say(
            &engine,
            json!({ "to": w.to_string(), "text": "Check the PowerShell installer on ARM." }),
        )
        .await,
    );
    board_task(
        &engine,
        folder,
        "Sign the PowerShell installer",
        WorkTaskStatus::Done,
        |_| {},
    )
    .await;
    // Two conversations: the owner's own, and one a dispatch made.
    let (own, own_detail) = parsed_session(
        &engine,
        folder,
        "Windows packaging",
        "the PowerShell build fails",
        "Fixed: quote the path.",
    )
    .await;
    let (made, made_detail) = parsed_session(
        &engine,
        folder,
        "Dispatched packaging",
        "build with PowerShell",
        "PowerShell build is green.",
    )
    .await;
    {
        use sea_orm::{ActiveModelTrait, Set};
        let d = svc::create_dispatch(
            conn,
            NewDispatch {
                bot_id: p,
                mode: DispatchMode::Chat,
                work_snapshot_json: "{}".into(),
                folder_id: Some(folder),
                deliverable: None,
                title: "packaging".into(),
                prompt: "packaging".into(),
                origin_batch_id: None,
                on_done: None,
                lineage: Default::default(),
                done_when: None,
                pr_fix: None,
                is_check: false,
            },
        )
        .await
        .unwrap();
        let mut am: crate::db::entities::personal_agent_dispatch::ActiveModel = d.into();
        am.conversation_id = Set(Some(made));
        am.update(conn).await.unwrap();
    }
    let makers = Makers::load(&host.db).await;
    for (id, detail) in [(own, &own_detail), (made, &made_detail)] {
        history::index_session(
            &host.db,
            &host.history,
            &makers,
            id,
            detail.summary.updated_at,
            detail,
        )
        .await;
    }

    // Found everywhere, the owner's own conversation once, above the
    // dispatched one, with its link and its last answer.
    let out = call_tool(&engine, "history_search", json!({ "query": "PowerShell" })).await;
    assert!(out.ok, "{}", out.text);
    let hits = out.data["hits"].as_array().unwrap().clone();
    let sources: Vec<&str> = hits.iter().map(|h| h["source"].as_str().unwrap()).collect();
    for s in ["timeline", "message", "task", "session"] {
        assert!(sources.contains(&s), "{s} in {sources:?}");
    }
    assert!(
        !hits
            .iter()
            .any(|h| h["ref_id"] == writing.id && h["source"] == "timeline"),
        "not while written"
    );
    let at = |id: i32| {
        hits.iter()
            .position(|h| h["source"] == "session" && h["ref_id"] == id)
            .unwrap()
    };
    assert!(at(own) < at(made), "the owner's own first: {}", out.text);
    assert_eq!(
        hits.iter()
            .filter(|h| h["source"] == "session" && h["ref_id"] == own)
            .count(),
        1
    );
    assert!(
        out.text
            .contains(&format!("[Windows packaging](codeg://session/{own})")),
        "{}",
        out.text
    );
    assert!(out.text.contains("handed out by"), "{}", out.text);
    assert!(out.text.contains("«PowerShell»"), "{}", out.text);
    assert!(out.text.contains("project pa-history"), "{}", out.text);

    // Chinese by any three characters; two are looked for in the last 90
    // days.
    let out = call_tool(&engine, "history_search", json!({ "query": "打包脚本" })).await;
    let hits = out.data["hits"].as_array().unwrap();
    assert_eq!(hits[0]["row_id"], asked.id);
    assert_eq!(hits[0]["bot_id"], p);
    // The owner's message the turn answers is not found for it.
    let q = history::Query {
        text: "打包脚本".into(),
        skip_rows: vec![asked.id],
        ..Default::default()
    };
    let found = history::search(&host.db, Some(&host.history), &q)
        .await
        .unwrap();
    assert!(found.hits.iter().all(|h| h.row_id != Some(asked.id)));
    let out = call_tool(&engine, "history_search", json!({ "query": "打包" })).await;
    assert_eq!(out.data["short"], true);
    assert!(out.text.contains("last 90 days"), "{}", out.text);
    assert_eq!(out.data["hits"][0]["row_id"], asked.id);
    // Scope and project.
    let out = call_tool(
        &engine,
        "history_search",
        json!({ "query": "PowerShell", "scope": "tasks" }),
    )
    .await;
    assert!(out.data["hits"]
        .as_array()
        .unwrap()
        .iter()
        .all(|h| h["source"] == "task"));
    let out = call_tool(
        &engine,
        "history_search",
        json!({ "query": "PowerShell", "project_id": folder + 1000 }),
    )
    .await;
    assert!(out.text.starts_with("Nothing found"), "{}", out.text);
    assert!(
        !call_tool(
            &engine,
            "history_search",
            json!({ "query": "x", "scope": "web" })
        )
        .await
        .ok
    );
    assert!(
        !call_tool(
            &engine,
            "history_search",
            json!({ "query": "x", "since": "last week" })
        )
        .await
        .ok
    );

    // Settled, the reply is found.
    svc::update_row_data(
        conn,
        writing.id,
        Some("写完了 PowerShell 的说明".into()),
        Some(json!({ "state": "done" })),
    )
    .await
    .unwrap();
    let out = call_tool(&engine, "history_search", json!({ "query": "写完了" })).await;
    assert_eq!(out.data["hits"][0]["row_id"], writing.id, "{}", out.text);

    // The owner turns the conversations and the tasks off: they leave.
    engine
        .apply_settings(&[
            change("prefs.history_sessions", json!("off")),
            change("prefs.history_tasks", json!("off")),
        ])
        .await
        .unwrap();
    for _ in 0..100 {
        if !store::has_source(conn, "session").await.unwrap()
            && !store::has_source(conn, "task").await.unwrap()
        {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    assert!(!store::has_source(conn, "session").await.unwrap());
    assert!(!store::has_source(conn, "task").await.unwrap());
    let out = call_tool(&engine, "history_search", json!({ "query": "PowerShell" })).await;
    let sources: Vec<&str> = out.data["hits"]
        .as_array()
        .unwrap()
        .iter()
        .map(|h| h["source"].as_str().unwrap())
        .collect();
    assert!(
        sources.iter().all(|s| *s == "timeline" || *s == "message"),
        "{sources:?}"
    );
    assert!(
        out.text.contains("all conversations left out"),
        "{}",
        out.text
    );
    // A conversation parsed meanwhile — before the switch, written after
    // the clearing — is not taken in, nor its stamp.
    history::index_session(
        &host.db,
        &host.history,
        &makers,
        own,
        own_detail.summary.updated_at,
        &own_detail,
    )
    .await;
    assert!(!store::has_source(conn, "session").await.unwrap());
    assert!(!history::read_sessions(&host.db, &host.history, None).await);
    assert!(!store::has_source(conn, "session").await.unwrap());
    let st = history::status(&host.db, Some(&host.history)).await;
    assert!(!st.sessions_on && !st.tasks_on);

    // On again: read anew.
    engine
        .apply_settings(&[
            change("prefs.history_sessions", json!("on")),
            change("prefs.history_tasks", json!("on")),
        ])
        .await
        .unwrap();
    super::history::read_rows(&host.db, &host.history).await;
    let out = call_tool(
        &engine,
        "history_search",
        json!({ "query": "Sign the PowerShell", "scope": "tasks" }),
    )
    .await;
    assert_eq!(
        out.data["hits"].as_array().unwrap().len(),
        1,
        "{}",
        out.text
    );
    let st = history::status(&host.db, Some(&host.history)).await;
    assert_eq!(st.sessions_total, 2);
    // A deleted conversation leaves the index.
    history::index_session(
        &host.db,
        &host.history,
        &makers,
        made,
        made_detail.summary.updated_at,
        &made_detail,
    )
    .await;
    async fn hits_for(db: &crate::db::AppDatabase, text: &str) -> Vec<super::history::Hit> {
        let q = super::history::Query {
            text: text.into(),
            ..Default::default()
        };
        super::history::search(db, None, &q).await.unwrap().hits
    }
    assert!(hits_for(&host.db, "green")
        .await
        .iter()
        .any(|h| h.ref_id == made));
    crate::db::service::conversation_service::soft_delete(conn, made)
        .await
        .unwrap();
    history::tidy(&host.db, &host.history).await;
    assert!(!hits_for(&host.db, "green")
        .await
        .iter()
        .any(|h| h.ref_id == made));
    assert_eq!(
        history::status(&host.db, Some(&host.history))
            .await
            .sessions_total,
        1
    );

    // A long text is found to its end; a task's result after a long ask.
    let mut long = NewRow::new(
        TimelineKind::Reply,
        format!("{} the zebrafish decision stands", "word ".repeat(2_000)),
    );
    long.data = Some(json!({ "state": "done" }));
    let long = svc::insert_row(conn, p, long).await.unwrap();
    board_task(&engine, folder, "Long ask", WorkTaskStatus::Done, |am| {
        use sea_orm::Set;
        am.config = Set(json!({ "display_text": "ask ".repeat(3_000) }).to_string());
        am.result_summary = Set(Some("the octopus outcome".into()));
    })
    .await;
    history::read_rows(&host.db, &host.history).await;
    let hits = hits_for(&host.db, "zebrafish").await;
    assert_eq!(
        hits.first().and_then(|h| h.row_id),
        Some(long.id),
        "{hits:?}"
    );
    assert!(hits_for(&host.db, "octopus outcome")
        .await
        .iter()
        .any(|h| h.source == "task"));

    // A deleted assistant's rows and the messages it sent do not come up,
    // and a rebuild does not bring them back.
    let worker = host.engine_for(Some(w)).await.unwrap();
    let said = svc::insert_row(
        conn,
        w,
        NewRow::new(TimelineKind::Owner, "the narwhal plan for Dev"),
    )
    .await
    .unwrap();
    sent_id(
        &say(
            &worker,
            json!({ "to": p.to_string(), "text": "the narwhal plan is ready" }),
        )
        .await,
    );
    history::read_rows(&host.db, &host.history).await;
    assert_eq!(hits_for(&host.db, "narwhal").await.len(), 2);
    {
        use sea_orm::{ActiveModelTrait, Set};
        let row = svc::get_bot(conn, w).await.unwrap().unwrap();
        let mut am: crate::db::entities::personal_agent::ActiveModel = row.into();
        am.deleted_at = Set(Some(chrono::Utc::now()));
        am.update(conn).await.unwrap();
    }
    assert!(
        hits_for(&host.db, "narwhal").await.is_empty(),
        "not before the tidying either"
    );
    store::clear_all(conn).await.unwrap();
    history::read_rows(&host.db, &host.history).await;
    assert!(!store::has_docs(conn, "timeline", said.id).await.unwrap());
    assert!(hits_for(&host.db, "narwhal").await.is_empty());
    assert!(
        !hits_for(&host.db, "zebrafish").await.is_empty(),
        "the rest read again"
    );
}

// ── 2.11 the profile and the weekly review ──────────────────────────────────

#[test]
fn the_profile_takes_the_owners_hours_and_the_week_is_stated_with_its_questions() {
    // A thread of its own with room, as the time machine's test.
    std::thread::Builder::new()
        .stack_size(16 << 20)
        .spawn(|| {
            tokio::runtime::Builder::new_current_thread()
                .enable_all()
                .build()
                .unwrap()
                .block_on(profile_steps())
        })
        .unwrap()
        .join()
        .unwrap();
}

async fn profile_steps() {
    use super::prefs::SettingChange;
    use super::{presence, profile, weekly};
    use crate::commands::personal_agent::{
        personal_agent_profile_update_core as update, ProfileOp,
    };
    use crate::db::entities::personal_agent_notice::{NoticeKind, NoticeLevel, NoticeState};
    use crate::db::service::personal_agent_service::NewNotice;
    use crate::models::personal_agent_prefs::ChatChanges;
    use chrono::{Duration, TimeZone, Utc};
    use sea_orm::{ActiveModelTrait, EntityTrait, Set};

    let (host, w, _tmp) = hosted().await;
    let engine = host.primary();
    let p = engine.bot().await;
    let db = &host.db;
    let conn = &db.conn;
    engine
        .apply_settings(&[SettingChange {
            key: "prefs.time_zone".into(),
            value: json!("Asia/Shanghai"),
        }])
        .await
        .unwrap();
    let tz: chrono_tz::Tz = "Asia/Shanghai".parse().unwrap();
    // Wednesday 2026-11-11, Shanghai.
    let sh = |h: u32, m: u32| {
        tz.with_ymd_and_hms(2026, 11, 11, h, m, 0)
            .unwrap()
            .with_timezone(&Utc)
    };

    // ── 1. the owner's hours win, and later learning does not override ──
    let view = update(
        db,
        ProfileOp::Hours {
            day: "workday".into(),
            start: Some("10:00".into()),
            end: Some("20:00".into()),
        },
    )
    .await
    .unwrap();
    assert!(view.hours.workday.set && view.hours.workday.learned);
    assert_eq!(
        (view.hours.workday.start, view.hours.workday.end),
        (600, 1200)
    );
    assert!(!view.learned_hours.workday.set, "what is learned is apart");
    assert!(!view.hours.restday.set);
    let prefs = engine.prefs().await;
    let h = presence::hours(conn, &prefs, sh(12, 0)).await;
    assert!(
        super::reach::is_quiet(&prefs, &h, tz, sh(9, 30)),
        "before their 10:00"
    );
    assert!(!super::reach::is_quiet(&prefs, &h, tz, sh(12, 0)));
    assert!(!super::reach::is_quiet(&prefs, &h, tz, sh(19, 59)));
    assert!(
        super::reach::is_quiet(&prefs, &h, tz, sh(20, 0)),
        "after their 20:00"
    );
    let day = presence::hours_day(sh(12, 0), tz);
    assert_eq!(
        super::brief::brief_early_at(&prefs, &h, tz, day),
        Some(sh(9, 45)),
        "the brief comes a quarter before their start"
    );
    // A month of 09:00–18:00 is learned; theirs still stands.
    for back in 1..=20 {
        let d = presence::hours_day(sh(12, 0), tz) - Duration::days(back);
        if super::due::is_rest_day(d) {
            continue;
        }
        for minute in [9 * 60, 9 * 60 + 5, 13 * 60, 17 * 60 + 50, 17 * 60 + 55] {
            for _ in 0..3 {
                crate::db::service::personal_agent_activity_service::add_minute(
                    conn,
                    d,
                    minute / presence::SLOT_MINUTES,
                    Utc::now(),
                )
                .await
                .unwrap();
            }
        }
    }
    let learned = presence::learned_hours(conn, &prefs, sh(12, 0)).await;
    assert!(learned.workday.learned && !learned.workday.set);
    assert_eq!(learned.workday.start, 9 * 60);
    let h = presence::hours(conn, &prefs, sh(12, 0)).await;
    assert_eq!(
        (h.workday.start, h.workday.end),
        (600, 1200),
        "not overridden"
    );
    // With the record off it stands too.
    let mut off = prefs.clone();
    off.presence = crate::models::personal_agent_prefs::OnOff::Off;
    assert_eq!(
        presence::hours(conn, &off, sh(12, 0)).await.workday.start,
        600
    );
    // Out of the day, or shorter than an hour: refused.
    assert!(update(
        db,
        ProfileOp::Hours {
            day: "workday".into(),
            start: Some("03:00".into()),
            end: Some("12:00".into()),
        },
    )
    .await
    .is_err());
    assert!(update(
        db,
        ProfileOp::Hours {
            day: "workday".into(),
            start: Some("10:00".into()),
            end: None,
        },
    )
    .await
    .is_err());
    // Let go: back to what is learned.
    let view = update(
        db,
        ProfileOp::Hours {
            day: "workday".into(),
            start: None,
            end: None,
        },
    )
    .await
    .unwrap();
    assert!(!view.hours.workday.set);
    assert_eq!(view.hours.workday.start, 9 * 60);

    // ── 2. the projects seen, one not minded ───────────────────────────────
    let a = crate::db::test_helpers::seed_folder(db, "/tmp/pa-profile-a").await;
    let b = crate::db::test_helpers::seed_folder(db, "/tmp/pa-profile-b").await;
    for _ in 0..3 {
        crate::db::test_helpers::seed_conversation(db, a, AgentType::ClaudeCode).await;
    }
    let in_b = crate::db::test_helpers::seed_conversation(db, b, AgentType::Codex).await;
    let seen = profile::observe(db, Utc::now()).await;
    assert_eq!(seen.projects.len(), 2);
    assert_eq!(seen.projects[0].folder_id, a, "most active first");
    assert_eq!(seen.projects[0].recent, 3);
    assert_eq!(seen.agents[0].agent_type, "claude_code");
    assert_eq!(seen.agents[0].percent, 75);
    let view = update(
        db,
        ProfileOp::Project {
            folder_id: b,
            excluded: true,
        },
    )
    .await
    .unwrap();
    assert!(view.projects.iter().any(|x| x.folder_id == b && x.excluded));
    let folders = super::overview::Folders::load(db).await;
    let recent = profile::recent_projects(db, &folders, Utc::now()).await;
    assert!(recent.contains(&a) && !recent.contains(&b));
    let line = profile::owner_line(&profile::observe(db, Utc::now()).await).unwrap();
    assert!(
        line.contains("pa-profile-a") && !line.contains("pa-profile-b"),
        "{line}"
    );
    let _ = in_b;

    // ── 3. grades ──────────────────────────────────────────────────────────
    let new = |title: &str, bot: i32| NewDispatch {
        bot_id: bot,
        mode: DispatchMode::Chat,
        work_snapshot_json: json!({ "name": "Dev", "agent_type": "codex" }).to_string(),
        folder_id: Some(a),
        deliverable: None,
        title: title.into(),
        prompt: title.into(),
        origin_batch_id: None,
        on_done: None,
        lineage: Default::default(),
        done_when: None,
        pr_fix: None,
        is_check: false,
    };
    let mut made = Vec::new();
    for (i, (state, turns, minutes)) in [
        (DispatchState::Completed, 1, 10),
        (DispatchState::Completed, 2, 50),
        (DispatchState::Failed, 1, 5),
    ]
    .into_iter()
    .enumerate()
    {
        let d = svc::create_dispatch(conn, new(&format!("work {i}"), w))
            .await
            .unwrap();
        let mut am: crate::db::entities::personal_agent_dispatch::ActiveModel = d.clone().into();
        am.state = Set(state);
        am.turns = Set(turns);
        am.finished_at = Set(Some(d.created_at + Duration::minutes(minutes)));
        am.update(conn).await.unwrap();
        made.push(d.id);
    }
    let by_bot = profile::grades(db, Utc::now()).await;
    let g = &by_bot[&w];
    assert_eq!((g.dispatches, g.settled, g.first_pass), (3, 3, 1));
    assert_eq!(g.first_pass_rate, Some(33));
    assert_eq!(g.avg_minutes, Some(30));
    let grades = crate::commands::personal_agent::personal_agent_grades_core(db).await;
    assert_eq!(grades.bots[&w].first_pass, 1);
    // Apart (7.9): this assistant's chats on Codex, one cell.
    assert_eq!(grades.cells.len(), 1);
    assert_eq!(
        (
            grades.cells[0].bot_id,
            grades.cells[0].agent_type,
            grades.cells[0].mode
        ),
        (Some(w), AgentType::Codex, DispatchMode::Chat)
    );
    assert_eq!(grades.cells[0].grade.settled, 3);

    // ── 4. the week ────────────────────────────────────────────────────────
    // Four changes made at the owner's word, three undone.
    for (i, undone) in [true, true, true, false].into_iter().enumerate() {
        let mut row = NewRow::new(TimelineKind::Notice, format!("changed {i}"));
        row.data = Some(json!({ "notice": "changed", "why": "owner" }));
        let (n, _) = svc::create_notice_with_row(
            conn,
            p,
            NewNotice {
                kind: NoticeKind::Changed,
                subject_key: None,
                level: NoticeLevel::Low,
                batch_id: None,
                payload: json!({ "why": "owner" }),
            },
            row,
        )
        .await
        .unwrap();
        svc::move_notice(conn, n.id, &[NoticeState::Open], NoticeState::Acted)
            .await
            .unwrap();
        if undone {
            svc::move_notice(conn, n.id, &[NoticeState::Acted], NoticeState::Undone)
                .await
                .unwrap();
        }
    }
    // A worker nobody woke for three weeks.
    let idle = worker_row(&engine, "Idle").await;
    {
        let row = crate::db::entities::personal_agent::Entity::find_by_id(idle)
            .one(conn)
            .await
            .unwrap()
            .unwrap();
        let mut am: crate::db::entities::personal_agent::ActiveModel = row.into();
        am.created_at = Set(Utc::now() - Duration::days(21));
        am.update(conn).await.unwrap();
    }
    // Tokens of the work the worker handed out.
    let conv = crate::db::test_helpers::seed_conversation(db, a, AgentType::Codex).await;
    {
        let mut am: crate::db::entities::personal_agent_dispatch::ActiveModel =
            svc::get_dispatch(conn, made[0])
                .await
                .unwrap()
                .unwrap()
                .into();
        am.conversation_id = Set(Some(conv));
        am.update(conn).await.unwrap();
        crate::db::entities::token_usage_turn::ActiveModel {
            conversation_id: Set(conv),
            turn_key: Set("t1".into()),
            occurred_at: Set(Utc::now()),
            model: Set(None),
            input_tokens: Set(1000),
            output_tokens: Set(234),
            cache_creation_tokens: Set(0),
            cache_read_tokens: Set(0),
            total_tokens: Set(1234),
            duration_ms: Set(0),
            ..Default::default()
        }
        .insert(conn)
        .await
        .unwrap();
        // That work delegated on to a session of its own: the worker's too.
        let child = crate::db::test_helpers::seed_conversation(db, a, AgentType::ClaudeCode).await;
        let row = crate::db::entities::conversation::Entity::find_by_id(child)
            .one(conn)
            .await
            .unwrap()
            .unwrap();
        let mut am: crate::db::entities::conversation::ActiveModel = row.into();
        am.parent_id = Set(Some(conv));
        am.update(conn).await.unwrap();
        crate::db::entities::token_usage_turn::ActiveModel {
            conversation_id: Set(child),
            turn_key: Set("t2".into()),
            occurred_at: Set(Utc::now()),
            model: Set(None),
            input_tokens: Set(100),
            output_tokens: Set(0),
            cache_creation_tokens: Set(0),
            cache_read_tokens: Set(0),
            total_tokens: Set(100),
            duration_ms: Set(0),
            ..Default::default()
        }
        .insert(conn)
        .await
        .unwrap();
    }
    // A pull request codeg fixed by itself: a round on its failed checks
    // this week, one on a conflict long before, one on review feedback.
    {
        use crate::db::service::personal_agent_watch_service as wsvc;
        use crate::personal_agent::pr_auto::{Auto, Cause, How, Round};
        let (watch, _) = wsvc::insert_or_get(
            conn,
            wsvc::NewWatch {
                bot_id: p,
                target: crate::forge::DeliveryTarget {
                    provider: crate::forge::ForgeProvider::GitHub,
                    server_host: "github.com".into(),
                    account_id: "a".into(),
                    owner_repo: "acme/app".into(),
                },
                kind: "pr".into(),
                number: 7,
                folder_id: None,
                work_task_id: None,
                dispatch_id: None,
                source: "task".into(),
                state: crate::db::entities::personal_agent_watch::WatchState::Watching,
                url: None,
                title: None,
                quiet_first: true,
            },
        )
        .await
        .unwrap();
        let round = |cause, at| Round {
            n: 1,
            cause,
            head: "h1".into(),
            dispatch_id: made[0],
            how: How::Task,
            at,
        };
        let auto = Auto {
            rounds: vec![
                round(Cause::Conflict, Utc::now() - Duration::days(30)),
                round(Cause::Checks, Utc::now()),
                round(Cause::Feedback, Utc::now()),
            ],
            ..Default::default()
        };
        wsvc::update(
            conn,
            watch.id,
            None,
            wsvc::WatchWrite {
                auto: Some(Some(serde_json::to_string(&auto).unwrap())),
                ..Default::default()
            },
        )
        .await
        .unwrap();
    }
    profile::count_held(db, presence::hours_day(Utc::now(), tz), "merged").await;
    profile::count_held(db, presence::hours_day(Utc::now(), tz), "merged").await;
    profile::count_held(db, presence::hours_day(Utc::now(), tz), "deferred").await;
    let prefs = engine.prefs().await;
    let today = presence::hours_day(Utc::now(), tz);
    let span = weekly::WeekSpan {
        first: weekly::monday_of(today),
        end: weekly::monday_of(today) + Duration::days(7),
    };
    let week = weekly::gather(db, &prefs, span, Utc::now()).await;
    assert_eq!(week.dispatched, 3);
    assert_eq!(
        (week.completed, week.failed, week.first_pass, week.settled),
        (2, 1, 1, 3)
    );
    assert_eq!(week.by_bot[0].id, w);
    assert_eq!((week.changes, week.changes_undone), (4, 3));
    assert_eq!(week.ci_fixed, 1, "this week's round on its checks");
    assert!(weekly::lines(&week)[0].contains("fixed by codeg 1"));
    let read = weekly::lines(&week).join("\n");
    assert!(
        !read.contains("executor"),
        "no executor config's name in what the brain reads: {read}"
    );
    let card = super::tools::without_executors(serde_json::to_value(&week).unwrap());
    assert!(card.get("by_executor").is_none(), "{card}");
    assert!(card.get("by_bot").is_some(), "{card}");
    assert_eq!(week.tokens, 1334);
    assert_eq!(week.tokens_by_bot[0].bot_id, w);
    assert_eq!(
        week.tokens_by_bot[0].handed_out, 1334,
        "a delegation's session is the work's"
    );
    assert_eq!((week.held.merged, week.held.deferred), (2, 1));
    assert!(week.so_far);
    let undo = week
        .asks
        .iter()
        .find(|x| x.rule == "undo")
        .expect("asks about the undoing");
    assert_eq!((undo.undone, undo.made), (3, 4));
    let asked_idle: Vec<_> = week.asks.iter().filter(|x| x.rule == "idle_bot").collect();
    assert_eq!(
        asked_idle.len(),
        1,
        "only the one nobody woke: {asked_idle:?}"
    );
    assert_eq!(asked_idle[0].bot_id, Some(idle));
    // The brain's materials state it.
    let m = super::brief::Material {
        kind: "brief".into(),
        day: today.format("%Y-%m-%d").to_string(),
        week: Some(week.clone()),
        ..Default::default()
    };
    assert!(!m.is_empty(), "a week to review is something to say");
    let text = super::brief::material_text(&m, tz);
    assert!(
        text.contains(&format!("## The week {}", week.label)),
        "{text}"
    );
    assert!(text.contains("tokens by assistant: Dev"), "{text}");
    assert!(
        text.contains("the owner undid 3 of the 4 changes"),
        "{text}"
    );

    // ── 5. its questions, as cards ─────────────────────────────────────────
    engine.raise_week_asks(&week, &prefs).await;
    engine.raise_week_asks(&week, &prefs).await;
    let cards =
        crate::db::service::personal_agent_rule_service::open_of_kind(conn, NoticeKind::Rule)
            .await
            .unwrap();
    assert_eq!(cards.len(), 2, "once a week each");
    let card_of = |rule: &str| {
        cards
            .iter()
            .find(|n| {
                serde_json::from_str::<serde_json::Value>(&n.payload).unwrap()["rule"] == rule
            })
            .unwrap()
            .id
    };
    engine
        .act_on_notice(card_of("undo"), "ask_first")
        .await
        .unwrap();
    assert_eq!(
        engine.prefs().await.chat_changes,
        ChatChanges::Show,
        "show such changes first"
    );
    // Deleting goes through the page; the card does not delete.
    assert!(engine
        .act_on_notice(card_of("idle_bot"), "delete")
        .await
        .is_err());
    engine
        .act_on_notice(card_of("idle_bot"), "hide")
        .await
        .unwrap();
    assert!(svc::get_bot(conn, idle).await.unwrap().unwrap().hidden);
    // Hidden: not asked about again.
    let again = weekly::gather(db, &engine.prefs().await, span, Utc::now()).await;
    assert!(again.asks.iter().all(|x| x.rule != "idle_bot"));
    assert!(
        again.asks.iter().all(|x| x.rule != "undo"),
        "changes are shown first now"
    );

    // ── 6. the record of answers off: what codeg lowered goes back ─────────
    crate::db::service::personal_agent_rule_service::set_data(
        conn,
        "failed",
        crate::db::service::personal_agent_rule_service::RULE_ITSELF,
        &json!({ "quiet_since": Utc::now().to_rfc3339() }),
        Utc::now(),
    )
    .await
    .unwrap();
    assert!(super::rules::quiet_since(db, "failed").await.is_some());
    engine
        .apply_settings(&[SettingChange {
            key: "prefs.reactions".into(),
            value: json!("off"),
        }])
        .await
        .unwrap();
    assert!(super::rules::quiet_since(db, "failed").await.is_none());
    assert!(super::presence::profile(db).await.cards.is_empty());
    assert!(
        !super::rules::after_answer(db, "failed", false).await,
        "nothing is lowered with it off"
    );

    // ── 7. clearing forgets what was learned, keeps what they set ──────────
    update(
        db,
        ProfileOp::Hours {
            day: "restday".into(),
            start: Some("11:00".into()),
            end: Some("16:00".into()),
        },
    )
    .await
    .unwrap();
    let view = update(db, ProfileOp::Clear).await.unwrap();
    assert!(view.cleared_at.is_some());
    assert!(
        !view.learned_hours.workday.learned,
        "the minutes are forgotten"
    );
    assert!(view.hours.restday.set, "theirs stays");
    assert!(view.projects.is_empty() || view.seen_since > Utc::now() - Duration::minutes(1));
}

#[tokio::test]
async fn routines_the_owner_asked_to_see_first_wait_on_a_card_and_count_among_the_changes_undone() {
    use super::prefs::SettingChange;
    use crate::db::entities::personal_agent_notice::NoticeKind;
    let (engine, _tmp) = configured().await;
    let bot = engine.bot().await;
    let db = &engine.db;
    let prefs = engine.prefs().await;
    // The owner's day, in the zone the week is gathered in: in UTC, early on
    // a Monday in a zone ahead of it is still last week.
    let today = super::presence::hours_day(
        chrono::Utc::now(),
        super::clock::zone_of(&prefs.time_zone),
    );
    let span = super::weekly::WeekSpan {
        first: super::weekly::monday_of(today),
        end: super::weekly::monday_of(today) + chrono::Duration::days(7),
    };
    // Made at the owner's word: the made card stays open (its [Undo] is on
    // it) and still counts as made; one undone.
    let mut cards = Vec::new();
    for i in 0..4 {
        let out = call(
            &engine,
            "routine_create",
            json!({ "title": format!("Check {i}"), "what": "Look.", "cron": "0 9 * * *" }),
        )
        .await;
        assert!(out.ok, "{}", out.text);
        cards.push(out.data["notice_id"].as_i64().unwrap() as i32);
    }
    engine.act_on_notice(cards[0], "undo").await.unwrap();
    let week = super::weekly::gather(db, &prefs, span, chrono::Utc::now()).await;
    assert_eq!(
        (week.changes, week.changes_undone),
        (4, 1),
        "kept routines are made too"
    );
    assert!(
        week.asks.iter().all(|a| a.rule != "undo"),
        "one of four is no pattern"
    );
    // Two more undone: three of four.
    engine.act_on_notice(cards[1], "undo").await.unwrap();
    engine.act_on_notice(cards[2], "undo").await.unwrap();
    let week = super::weekly::gather(db, &prefs, span, chrono::Utc::now()).await;
    let undo = week.asks.iter().find(|a| a.rule == "undo").expect("asked");
    assert_eq!((undo.undone, undo.made), (3, 4));
    // Clearing what codeg learned: those undos count no more.
    super::profile::clear(db).await.unwrap();
    let week = super::weekly::gather(db, &prefs, span, chrono::Utc::now()).await;
    assert!(week.asks.iter().all(|a| a.rule != "undo"), "cleared");

    // The owner sees such changes first: a routine waits on a card.
    engine
        .apply_settings(&[SettingChange {
            key: "prefs.chat_changes".into(),
            value: json!("show"),
        }])
        .await
        .unwrap();
    let before = rsvc::list_of(&db.conn, bot).await.unwrap().len();
    let out = call(
        &engine,
        "routine_create",
        json!({ "title": "Nightly", "what": "Tidy up.", "cron": "0 2 * * *" }),
    )
    .await;
    assert!(
        out.ok && out.text.contains("sees such changes first"),
        "{}",
        out.text
    );
    assert_eq!(
        rsvc::list_of(&db.conn, bot).await.unwrap().len(),
        before,
        "nothing made yet"
    );
    let notice = out.data["notice_id"].as_i64().unwrap() as i32;
    let n = svc::get_notice(&db.conn, notice).await.unwrap().unwrap();
    assert_eq!(n.kind, NoticeKind::Routine);
    let card = routine_cards(&engine, "proposal").await;
    assert_eq!(data_of(card.last().unwrap())["confirm"], true);
    // Not a suggestion: "don't suggest these" does not apply to it.
    assert_eq!(
        super::rules::rule_of_card(&n, &data_of(card.last().unwrap())),
        None
    );
    // It waits on the owner.
    let row = svc::get_bot(&db.conn, bot).await.unwrap().unwrap();
    let (_, needs) = super::live::live_from_db_with_needs(db, &row).await;
    assert!(needs.iter().any(|x| x.kind == "changed"), "{needs:?}");
    // Said yes to: made, as the owner's own.
    engine.act_on_notice(notice, "accept").await.unwrap();
    let made = rsvc::list_of(&db.conn, bot).await.unwrap();
    let nightly = made.iter().find(|r| r.title == "Nightly").unwrap();
    assert_eq!(nightly.source, "owner");
    // A change too.
    let out = call(
        &engine,
        "routine_update",
        json!({ "routine_id": nightly.id, "action": "pause" }),
    )
    .await;
    assert!(
        out.ok && out.text.contains("sees such changes first"),
        "{}",
        out.text
    );
    assert!(
        rsvc::get(&db.conn, nightly.id)
            .await
            .unwrap()
            .unwrap()
            .enabled,
        "not yet"
    );
    // A new time: the card shows the routine as it would be, what it is
    // beside it.
    let out = call(
        &engine,
        "routine_update",
        json!({ "routine_id": nightly.id, "cron": "30 4 * * *" }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let card = routine_cards(&engine, "proposal").await;
    let shown = data_of(card.last().unwrap());
    assert_eq!(shown["routine"]["cron"], "30 4 * * *");
    assert_eq!(shown["routine"]["id"], nightly.id);
    assert_eq!(shown["before"]["cron"], "0 2 * * *");
    let cron = |db: &crate::db::AppDatabase| {
        let conn = db.conn.clone();
        let id = nightly.id;
        async move { rsvc::get(&conn, id).await.unwrap().unwrap().cron }
    };
    assert_eq!(cron(db).await.as_deref(), Some("0 2 * * *"), "not yet");
    engine
        .act_on_notice(out.data["notice_id"].as_i64().unwrap() as i32, "accept")
        .await
        .unwrap();
    assert_eq!(cron(db).await.as_deref(), Some("30 4 * * *"));
    // The assistant's own suggestion still is one, and is refused while the
    // owner takes none.
    let out = call(
        &engine,
        "routine_create",
        json!({ "title": "Idea", "what": "x", "cron": "0 3 * * *", "suggest": true }),
    )
    .await;
    assert!(out.ok && out.text.starts_with("Suggested"), "{}", out.text);
}

#[tokio::test]
async fn clearing_what_was_learned_starts_the_count_of_dismissed_cards_anew() {
    use crate::db::entities::personal_agent_notice::{NoticeKind, NoticeLevel, NoticeState};
    use crate::db::service::personal_agent_service::NewNotice;
    let (engine, _tmp) = configured().await;
    let bot = engine.bot().await;
    let db = &engine.db;
    let dismiss = |object: String| {
        let engine = engine.clone();
        async move {
            let (n, _) = svc::create_notice_with_row(
                &engine.db.conn,
                bot,
                NewNotice {
                    kind: NoticeKind::Rule,
                    subject_key: Some(super::rules::subject("failed", &object)),
                    level: NoticeLevel::Normal,
                    batch_id: None,
                    payload: json!({ "rule": "failed", "object": object, "episode": object }),
                },
                NewRow::new(TimelineKind::Notice, "failed"),
            )
            .await
            .unwrap();
            svc::move_notice(
                &engine.db.conn,
                n.id,
                &[NoticeState::Open],
                NoticeState::Dismissed,
            )
            .await
            .unwrap();
            // Answers are ordered by when: one per moment.
            tokio::time::sleep(std::time::Duration::from_millis(5)).await;
        }
    };
    dismiss("dispatch:1".into()).await;
    dismiss("dispatch:2".into()).await;
    super::profile::clear(db).await.unwrap();
    tokio::time::sleep(std::time::Duration::from_millis(5)).await;
    dismiss("dispatch:3".into()).await;
    assert!(
        !super::rules::after_answer(db, "failed", false).await,
        "the two before clearing count no more"
    );
    dismiss("dispatch:4".into()).await;
    dismiss("dispatch:5".into()).await;
    assert!(
        super::rules::after_answer(db, "failed", false).await,
        "three since: lowered"
    );
}

// ── plans (7.6) ─────────────────────────────────────────────────────────────

use crate::db::entities::personal_agent_plan::PlanState;
use crate::db::entities::personal_agent_plan_step::StepState;
use crate::db::service::personal_agent_plan_service as psvc;

async fn plan_steps(
    engine: &PersonalAgentEngine,
    plan: i32,
) -> Vec<crate::db::entities::personal_agent_plan_step::Model> {
    psvc::steps_of(&engine.db.conn, plan).await.unwrap()
}

async fn plan_row(
    engine: &PersonalAgentEngine,
    plan: i32,
) -> crate::db::entities::personal_agent_plan::Model {
    psvc::get(&engine.db.conn, plan).await.unwrap().unwrap()
}

/// Wait for a plan's look a hook set off (it runs on its own task).
async fn until_step(
    engine: &PersonalAgentEngine,
    plan: i32,
    seq: i32,
    want: StepState,
) -> crate::db::entities::personal_agent_plan_step::Model {
    for _ in 0..200 {
        if let Some(s) = plan_steps(engine, plan)
            .await
            .into_iter()
            .find(|s| s.seq == seq)
        {
            // A step is claimed (running) before it is sent: under way is
            // once its message or dispatch is written too.
            let sent = s.message_id.is_some() || s.dispatch_id.is_some();
            if s.state == want && (want != StepState::Running || sent) {
                return s;
            }
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    panic!(
        "step {seq} never became {want:?}: {:?}",
        plan_steps(engine, plan)
            .await
            .into_iter()
            .find(|s| s.seq == seq)
    );
}

async fn plan_card(
    engine: &PersonalAgentEngine,
    plan: i32,
) -> (
    crate::db::entities::personal_agent_notice::Model,
    serde_json::Value,
) {
    let p = plan_row(engine, plan).await;
    let n = svc::get_notice(&engine.db.conn, p.notice_id.unwrap())
        .await
        .unwrap()
        .unwrap();
    let row = svc::get_row(&engine.db.conn, n.timeline_id.unwrap())
        .await
        .unwrap()
        .unwrap();
    (n, data_of(&row))
}

/// The plan event of a step's failure, as the assistant's turn takes it:
/// delivered in a batch, and the batch done.
async fn turn_takes_plan_events(engine: &PersonalAgentEngine) {
    let seg = open_segment(engine).await;
    let batch = svc::create_batch(
        &engine.db.conn,
        engine.bot().await,
        seg,
        BatchKind::Delivery,
        None,
    )
    .await
    .unwrap();
    let ids: Vec<i32> = svc::pending_events(&engine.db.conn, engine.bot().await)
        .await
        .unwrap()
        .into_iter()
        .filter(|e| e.kind == super::plans::PLAN_EVENT)
        .map(|e| e.id)
        .collect();
    svc::mark_events_delivered(&engine.db.conn, &ids, batch.id)
        .await
        .unwrap();
    svc::finish_batch_events(&engine.db.conn, batch.id)
        .await
        .unwrap();
}

#[tokio::test]
async fn a_plan_hands_each_step_out_once_the_steps_it_waits_for_are_done_and_ends_with_a_summary() {
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    let worker = host.engine_for(Some(w)).await.unwrap();
    let out = call(
        &primary,
        "plan_create",
        json!({
            "title": "Split the parser",
            "goal": "A faster parser.",
            "steps": [
                { "title": "Survey", "to": "Dev", "prompt": "Find the slow paths.", "done_when": "A list of the slow paths." },
                { "title": "Write it up", "to": w, "prompt": "Write the plan up.", "depends_on": [1] },
                { "title": "Check it", "to": "Dev", "prompt": "Check the write-up.", "depends_on": [1, 2] }
            ]
        }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let id = out.data["plan"]["id"].as_i64().unwrap() as i32;
    assert_eq!(plan_row(&primary, id).await.state, PlanState::Running);
    // Only the step that waits for nothing went out: a message wanting an
    // answer, carrying what done looks like and its place in the plan.
    let steps = plan_steps(&primary, id).await;
    assert_eq!(
        steps.iter().map(|s| s.state).collect::<Vec<_>>(),
        vec![StepState::Running, StepState::Pending, StepState::Pending]
    );
    let m1 = message(&primary, steps[0].message_id.unwrap()).await;
    assert!(m1.wants_reply);
    assert_eq!(m1.to_bot_id, w);
    for part in [
        "Find the slow paths.",
        "Done when:\nA list of the slow paths.",
        "step 1 of 3 of the plan \"Split the parser\"",
        "reply_to",
    ] {
        assert!(m1.body.contains(part), "{part} in {}", m1.body);
    }
    let (n, data) = plan_card(&primary, id).await;
    assert_eq!(
        n.kind,
        crate::db::entities::personal_agent_notice::NoticeKind::Plan
    );
    assert_eq!(data["plan"]["steps"][0]["state"], "running");
    // Its answer is the step's conclusion: the next step goes, with it.
    let back = say(&worker, json!({ "reply_to": format!("m{}", m1.id), "text": "Slow: the tokenizer and the AST walk." })).await;
    assert!(back.ok, "{}", back.text);
    let s1 = until_step(&primary, id, 1, StepState::Done).await;
    assert_eq!(
        s1.result.as_deref(),
        Some("Slow: the tokenizer and the AST walk.")
    );
    let s2 = until_step(&primary, id, 2, StepState::Running).await;
    assert_eq!(
        plan_steps(&primary, id).await[2].state,
        StepState::Pending,
        "step 3 waits for step 2 too"
    );
    let m2 = message(&primary, s2.message_id.unwrap()).await;
    assert!(
        m2.body.contains("Slow: the tokenizer and the AST walk."),
        "{}",
        m2.body
    );
    say(
        &worker,
        json!({ "reply_to": format!("m{}", m2.id), "text": "Written up." }),
    )
    .await;
    let s3 = until_step(&primary, id, 3, StepState::Running).await;
    say(
        &worker,
        json!({ "reply_to": format!("m{}", s3.message_id.unwrap()), "text": "Looks right." }),
    )
    .await;
    until_step(&primary, id, 3, StepState::Done).await;
    for _ in 0..200 {
        if plan_row(&primary, id).await.state == PlanState::Done {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    let p = plan_row(&primary, id).await;
    assert_eq!(p.state, PlanState::Done);
    // The assistant is woken to write the summary, with what each came to.
    let done = svc::pending_events(&primary.db.conn, primary.bot().await)
        .await
        .unwrap()
        .into_iter()
        .find(|e| {
            e.kind == super::plans::PLAN_EVENT && e.source_key.ends_with(&format!("plan:{id}:done"))
        })
        .expect("the summary is asked for");
    assert!(done.wake);
    assert!(
        done.summary.contains("summary card") && done.summary.contains("Looks right."),
        "{}",
        done.summary
    );
    let (n, data) = plan_card(&primary, id).await;
    assert_eq!(
        n.state,
        crate::db::entities::personal_agent_notice::NoticeState::Acted
    );
    assert_eq!(data["plan"]["done"], 3);
}

#[tokio::test]
async fn a_plan_shown_first_starts_on_the_owners_start_and_a_stop_hands_nothing_new_out() {
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    primary
        .apply_settings(&[change("prefs.plans", json!("ask"))])
        .await
        .unwrap();
    let out = call(
        &primary,
        "plan_create",
        json!({ "title": "Two things", "steps": [
            { "title": "One", "to": w, "prompt": "Do one." },
            { "title": "Two", "to": w, "prompt": "Do two." },
            { "title": "Three", "to": w, "prompt": "Do three.", "depends_on": [1] }
        ] }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    assert!(out.text.contains("Start"), "{}", out.text);
    let id = out.data["plan"]["id"].as_i64().unwrap() as i32;
    assert_eq!(plan_row(&primary, id).await.state, PlanState::Draft);
    assert!(plan_steps(&primary, id)
        .await
        .iter()
        .all(|s| s.state == StepState::Pending && s.message_id.is_none()));
    // Waits on the owner as a card to confirm.
    let needs = super::live::needs_for_test(&primary.db, primary.bot().await).await;
    assert!(needs.iter().any(|n| n.kind == "confirm"), "{needs:?}");
    // The clock does not start it either.
    primary.plan_tick().await;
    assert!(plan_steps(&primary, id)
        .await
        .iter()
        .all(|s| s.state == StepState::Pending));
    let (n, _) = plan_card(&primary, id).await;
    primary.act_on_notice(n.id, "start").await.unwrap();
    let steps = plan_steps(&primary, id).await;
    assert_eq!(
        steps.iter().map(|s| s.state).collect::<Vec<_>>(),
        vec![StepState::Running, StepState::Running, StepState::Pending]
    );
    assert!(
        !super::live::needs_for_test(&primary.db, primary.bot().await)
            .await
            .iter()
            .any(|n| n.kind == "confirm")
    );
    // Stopped: what runs runs on, nothing new goes out.
    primary.act_on_notice(n.id, "stop").await.unwrap();
    assert_eq!(plan_row(&primary, id).await.state, PlanState::Stopped);
    let worker = host.engine_for(Some(w)).await.unwrap();
    say(
        &worker,
        json!({ "reply_to": format!("m{}", steps[0].message_id.unwrap()), "text": "One done." }),
    )
    .await;
    until_step(&primary, id, 1, StepState::Done).await;
    primary.plan_tick().await;
    let s3 = plan_steps(&primary, id).await.remove(2);
    assert_eq!(s3.state, StepState::Stopped, "not handed out while stopped");
    assert!(s3.message_id.is_none());
    // A step under way canceled from the card.
    primary.act_on_notice(n.id, "cancel_step:2").await.unwrap();
    assert_eq!(plan_steps(&primary, id).await[1].state, StepState::Canceled);
    assert_eq!(
        message(&primary, steps[1].message_id.unwrap()).await.state,
        MessageState::Stopped
    );
    // Picked up again: step 3 goes.
    primary.act_on_notice(n.id, "start").await.unwrap();
    let s3 = plan_steps(&primary, id).await.remove(2);
    assert_eq!(s3.state, StepState::Running);
    // Step 2 was the owner's to cancel: stuck, but nobody is told urgently.
    let p = plan_row(&primary, id).await;
    assert_eq!(p.state, PlanState::Stuck);
    assert!(
        p.stuck_reason.as_deref().unwrap().contains("was canceled"),
        "{:?}",
        p.stuck_reason
    );
    assert!(super::plans::told_for_test(&p).stuck.is_empty());
}

#[tokio::test]
async fn a_step_still_failed_after_its_assistants_turn_makes_the_plan_stuck_until_it_is_picked_up()
{
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    role_assistant(&primary, "Researcher", true).await;
    let out = call(
        &primary,
        "plan_create",
        json!({ "title": "Research", "steps": [
            { "title": "Look", "mode": "chat", "prompt": "Look it up." },
            { "title": "Tell", "to": w, "prompt": "Write it down.", "depends_on": [1] },
            { "title": "Aside", "to": w, "prompt": "Unrelated." }
        ] }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let id = out.data["plan"]["id"].as_i64().unwrap() as i32;
    let s1 = plan_steps(&primary, id).await.remove(0);
    let d = s1.dispatch_id.expect("dispatched");
    assert!(dispatch_state(&primary, d)
        .await
        .prompt
        .contains("step 1 of 3 of the plan \"Research\""));
    // Its own step on the card: "self", with the agent its work ran on —
    // what its conversation opens with.
    let (_, card) = plan_card(&primary, id).await;
    assert_eq!(card["plan"]["steps"][0]["target_kind"], "self");
    assert!(card["plan"]["steps"][0]["agent_type"].is_string(), "{card}");
    // Its work fails.
    let started = settled(&primary, d).await;
    if started.state != DispatchState::Failed {
        let failed = svc::update_dispatch(
            &primary.db.conn,
            d,
            None,
            DispatchWrite {
                state: Some(DispatchState::Failed),
                error: Some(Some("boom".into())),
                ..Default::default()
            },
        )
        .await
        .unwrap()
        .unwrap();
        primary
            .record_progress(&failed, None, Some("boom".into()), "turn")
            .await;
    }
    let s1 = until_step(&primary, id, 1, StepState::Failed).await;
    assert_eq!(s1.failures, 1);
    // Its assistant is woken; the plan is not stuck while that turn is to
    // come, and what does not wait on the step went on.
    let ev = svc::pending_events(&primary.db.conn, primary.bot().await)
        .await
        .unwrap()
        .into_iter()
        .find(|e| e.kind == super::plans::PLAN_EVENT)
        .expect("woken");
    assert!(ev.wake);
    assert!(
        ev.summary
            .contains(&format!("dispatch_followup on dispatch #{d}")),
        "{}",
        ev.summary
    );
    primary.plan_tick().await;
    assert_eq!(plan_row(&primary, id).await.state, PlanState::Running);
    assert_eq!(
        plan_steps(&primary, id).await[2].state,
        StepState::Running,
        "the step aside went on"
    );
    assert_eq!(plan_steps(&primary, id).await[1].state, StepState::Pending);
    // Its turn went by with the step still failed: stuck, told once.
    turn_takes_plan_events(&primary).await;
    primary.plan_tick().await;
    let p = plan_row(&primary, id).await;
    assert_eq!(p.state, PlanState::Stuck);
    assert!(
        p.stuck_reason
            .as_deref()
            .unwrap()
            .starts_with("step 1 \"Look\" failed"),
        "{:?}",
        p.stuck_reason
    );
    assert_eq!(super::plans::told_for_test(&p).stuck.len(), 1);
    let needs = super::live::needs_for_test(&primary.db, primary.bot().await).await;
    assert!(needs.iter().any(|n| n.kind == "plan_stuck"), "{needs:?}");
    primary.plan_tick().await;
    assert_eq!(
        super::plans::told_for_test(&plan_row(&primary, id).await)
            .stuck
            .len(),
        1,
        "told once"
    );
    // Handed to a work assistant instead: running again.
    let out = call(
        &primary,
        "plan_update",
        json!({ "plan_id": id, "reason": "the researcher is down", "steps": [ { "id": 1, "to": w } ] }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let s1 = until_step(&primary, id, 1, StepState::Running).await;
    assert!(s1.message_id.is_some());
    assert_eq!(s1.attempt, 2);
    let p = plan_row(&primary, id).await;
    assert_eq!(p.state, PlanState::Running);
    assert!(p.stuck_reason.is_none());
    let (_, data) = plan_card(&primary, id).await;
    assert_eq!(
        data["plan"]["changes"][0]["items"][0]["fields"],
        json!(["who", "mode"])
    );
    assert_eq!(
        data["plan"]["changes"][0]["reason"],
        "the researcher is down"
    );
}

#[tokio::test]
async fn a_plan_is_checked_as_its_dispatches_would_be_and_a_change_to_steps_not_started_can_be_taken_back(
) {
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    // Checked as the dispatch it becomes — not what runs it, taken when the
    // step comes up.
    let refused = call(
        &primary,
        "plan_create",
        json!({ "title": "X", "steps": [ { "title": "A", "mode": "task", "prompt": "a" } ] }),
    )
    .await;
    assert!(!refused.ok);
    assert!(refused.text.starts_with("step 1:"), "{}", refused.text);
    let circle = call(
        &primary,
        "plan_create",
        json!({ "title": "X", "steps": [
            { "title": "A", "to": w, "prompt": "a", "depends_on": [2] },
            { "title": "B", "to": w, "prompt": "b", "depends_on": [1] }
        ] }),
    )
    .await;
    assert!(
        !circle.ok && circle.text.contains("circle"),
        "{}",
        circle.text
    );
    let me = call(
        &primary,
        "plan_create",
        json!({ "title": "X", "steps": [ { "title": "A", "to": primary.bot().await, "prompt": "a" } ] }),
    )
    .await;
    // Its own id is itself: a step it does itself, which takes a mode.
    assert!(!me.ok && me.text.contains("`mode`"), "{}", me.text);
    let out = call(
        &primary,
        "plan_create",
        json!({ "title": "Ship", "steps": [
            { "title": "Build", "to": w, "prompt": "Build it." },
            { "title": "Test", "to": w, "prompt": "Test it.", "depends_on": [1] }
        ] }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let id = out.data["plan"]["id"].as_i64().unwrap() as i32;
    // Step 1 runs: it cannot change; step 2 can, and a step is added.
    let busy = call(
        &primary,
        "plan_update",
        json!({ "plan_id": id, "steps": [ { "id": 1, "prompt": "Other." } ] }),
    )
    .await;
    assert!(!busy.ok && busy.text.contains("under way"), "{}", busy.text);
    let out = call(
        &primary,
        "plan_update",
        json!({ "plan_id": id, "steps": [
            { "id": 2, "prompt": "Test it on Windows too." },
            { "title": "Release", "to": w, "prompt": "Release it.", "depends_on": [2] }
        ] }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let steps = plan_steps(&primary, id).await;
    assert_eq!(steps.len(), 3);
    assert_eq!(steps[1].prompt, "Test it on Windows too.");
    assert_eq!(steps[2].deps(), vec![2]);
    // Removing step 2 lets step 3 wait for nothing it had.
    let out = call(
        &primary,
        "plan_update",
        json!({ "plan_id": id, "steps": [ { "id": 2, "remove": true } ] }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let steps = plan_steps(&primary, id).await;
    assert_eq!(steps.iter().map(|s| s.seq).collect::<Vec<_>>(), vec![1, 3]);
    assert!(steps[1].deps().is_empty());
    // Step 3 is free now and goes; the removal is taken back: step 2 comes
    // back, step 3 had started and keeps it.
    until_step(&primary, id, 3, StepState::Running).await;
    let (n, data) = plan_card(&primary, id).await;
    assert_eq!(data["plan"]["changes"][1]["undoable"], true);
    primary.act_on_notice(n.id, "undo:1").await.unwrap();
    let steps = plan_steps(&primary, id).await;
    assert_eq!(
        steps.iter().map(|s| s.seq).collect::<Vec<_>>(),
        vec![1, 2, 3]
    );
    assert_eq!(steps[1].prompt, "Test it on Windows too.");
    assert!(
        steps[2].deps().is_empty(),
        "step 3 started: it keeps the change"
    );
    let (_, data) = plan_card(&primary, id).await;
    assert_eq!(data["plan"]["changes"][1]["undone"], true);
    assert_eq!(data["plan"]["changes"][1]["kept"], json!([3]));
    // The first change's step 2 part is undone too; its step 3 started.
    primary.act_on_notice(n.id, "undo:0").await.unwrap();
    let steps = plan_steps(&primary, id).await;
    assert_eq!(steps[1].prompt, "Test it.");
    assert_eq!(steps.len(), 3, "the added step had started: kept");
}

/// Fail a plan step's dispatch as its work would.
async fn fail_dispatch(engine: &PersonalAgentEngine, d: i32) {
    let started = settled(engine, d).await;
    if started.state == DispatchState::Failed {
        return;
    }
    let failed = svc::update_dispatch(
        &engine.db.conn,
        d,
        None,
        DispatchWrite {
            state: Some(DispatchState::Failed),
            error: Some(Some("boom".into())),
            ..Default::default()
        },
    )
    .await
    .unwrap()
    .unwrap();
    engine
        .record_progress(&failed, None, Some("boom".into()), "turn")
        .await;
}

#[tokio::test]
async fn a_failed_step_followed_up_goes_on_and_a_change_delivered_again_is_made_once() {
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    role_assistant(&primary, "Researcher", true).await;
    let out = call(
        &primary,
        "plan_create",
        json!({ "title": "Research", "steps": [
            { "title": "Look", "mode": "chat", "prompt": "Look it up." },
            { "title": "Tell", "to": w, "prompt": "Write it down.", "depends_on": [1] }
        ] }),
    )
    .await;
    assert!(out.ok, "{}", out.text);
    let id = out.data["plan"]["id"].as_i64().unwrap() as i32;
    let d = plan_steps(&primary, id).await[0].dispatch_id.unwrap();
    fail_dispatch(&primary, d).await;
    until_step(&primary, id, 1, StepState::Failed).await;
    // Its assistant follows the dispatch up: the step is under way again.
    let again = svc::update_dispatch(
        &primary.db.conn,
        d,
        None,
        DispatchWrite {
            state: Some(DispatchState::Running),
            error: Some(None),
            ..Default::default()
        },
    )
    .await
    .unwrap()
    .unwrap();
    primary
        .record_progress(&again, None, None, "followup")
        .await;
    let s1 = until_step(&primary, id, 1, StepState::Running).await;
    assert!(s1.error.is_none());
    // Its work done: the step is, and the next goes.
    let done = svc::update_dispatch(
        &primary.db.conn,
        d,
        None,
        DispatchWrite {
            state: Some(DispatchState::Completed),
            result_excerpt: Some(Some("Found it.".into())),
            ..Default::default()
        },
    )
    .await
    .unwrap()
    .unwrap();
    primary
        .record_progress(&done, Some("Found it.".into()), None, "turn")
        .await;
    let s1 = until_step(&primary, id, 1, StepState::Done).await;
    assert_eq!(s1.result.as_deref(), Some("Found it."));
    until_step(&primary, id, 2, StepState::Running).await;
    for _ in 0..50 {
        if plan_row(&primary, id).await.state == PlanState::Running {
            break;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    assert_eq!(
        plan_row(&primary, id).await.state,
        PlanState::Running,
        "never stuck"
    );
    // A change made in a turn, then the same call again — in that turn, and
    // in the turn that delivers it again: one step added.
    let (_, first) = owner_turn(&primary, "pa-plan").await;
    let change = json!({ "plan_id": id, "reason": "one more", "steps": [ { "title": "Ship", "to": w, "prompt": "Ship it." } ] });
    let a = call(&primary, "plan_update", change.clone()).await;
    assert!(a.ok && a.data["changed"] == json!(true), "{}", a.text);
    let b = call(
        &primary,
        "plan_update",
        json!({ "plan_id": id, "reason": "worded afresh", "steps": [ { "title": "Ship", "to": w, "prompt": "Ship it." } ] }),
    )
    .await;
    assert_eq!(b.data["earlier"], json!(true), "{}", b.text);
    let (_, redelivery) = owner_turn(&primary, "pa-plan").await;
    primary
        .set_ledger_scope_for_test(vec![redelivery, first])
        .await;
    let c = call(&primary, "plan_update", change).await;
    assert_eq!(c.data["earlier"], json!(true), "{}", c.text);
    assert_eq!(plan_steps(&primary, id).await.len(), 3);
    assert_eq!(changes_count(&primary, id).await, 1);
}

async fn changes_count(engine: &PersonalAgentEngine, plan: i32) -> usize {
    serde_json::from_str::<Vec<serde_json::Value>>(&plan_row(engine, plan).await.changes)
        .unwrap()
        .len()
}

#[tokio::test]
async fn a_step_number_is_never_given_twice_and_a_restart_leaves_no_plan_without_its_card_or_summary(
) {
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    primary
        .apply_settings(&[change("prefs.plans", json!("ask"))])
        .await
        .unwrap();
    let out = call(
        &primary,
        "plan_create",
        json!({ "title": "Two", "steps": [
            { "title": "One", "to": w, "prompt": "Do one." },
            { "title": "Two", "to": w, "prompt": "Do two." }
        ] }),
    )
    .await;
    let id = out.data["plan"]["id"].as_i64().unwrap() as i32;
    // Step 2 removed, then a new step: it is step 3, not step 2 again.
    assert!(
        call(
            &primary,
            "plan_update",
            json!({ "plan_id": id, "steps": [ { "id": 2, "remove": true } ] })
        )
        .await
        .ok
    );
    let added = call(&primary, "plan_update", json!({ "plan_id": id, "steps": [ { "title": "Three", "to": w, "prompt": "Do three." } ] })).await;
    assert!(added.ok, "{}", added.text);
    let steps = plan_steps(&primary, id).await;
    assert_eq!(
        steps
            .iter()
            .map(|s| (s.seq, s.title.as_str()))
            .collect::<Vec<_>>(),
        vec![(1, "One"), (3, "Three")]
    );
    // Taking the removal back brings step 2 back as it was; step 3 stays.
    let (n, _) = plan_card(&primary, id).await;
    primary.act_on_notice(n.id, "undo:0").await.unwrap();
    let steps = plan_steps(&primary, id).await;
    assert_eq!(
        steps
            .iter()
            .map(|s| (s.seq, s.title.as_str(), s.prompt.as_str()))
            .collect::<Vec<_>>(),
        vec![
            (1, "One", "Do one."),
            (2, "Two", "Do two."),
            (3, "Three", "Do three.")
        ]
    );
    // A restart between making a plan and raising its card: the clock's
    // look raises it, and it waits on the owner as one to start.
    let bare = match psvc::create(
        &primary.db.conn,
        psvc::NewPlan {
            bot_id: primary.bot().await,
            title: "Bare".into(),
            goal: None,
            state: PlanState::Draft,
            origin_batch_id: None,
            for_input: None,
            origin_bot_id: None,
            origin_row_id: None,
            thread_id: None,
        },
        vec![psvc::NewStep::of(&plan_steps(&primary, id).await[0])],
        None,
        None,
    )
    .await
    .unwrap()
    {
        svc::Ledgered::New(p) => p,
        svc::Ledgered::Earlier(_) => unreachable!(),
    };
    assert!(bare.notice_id.is_none());
    primary.plan_tick().await;
    let (n, data) = plan_card(&primary, bare.id).await;
    assert_eq!(
        n.kind,
        crate::db::entities::personal_agent_notice::NoticeKind::Plan
    );
    assert_eq!(data["plan"]["title"], "Bare");
    // A restart between a plan's end and what its end owes: the summary is
    // asked for by the clock's look, once.
    psvc::update(
        &primary.db.conn,
        bare.id,
        None,
        psvc::PlanWrite {
            state: Some(PlanState::Done),
            // However long ago.
            ended_at: Some(Some(super::clock::now() - chrono::Duration::days(3))),
            ..Default::default()
        },
    )
    .await
    .unwrap();
    primary.plan_tick().await;
    primary.plan_tick().await;
    let asked: Vec<_> = svc::pending_events(&primary.db.conn, primary.bot().await)
        .await
        .unwrap()
        .into_iter()
        .filter(|e| e.source_key.ends_with(&format!("plan:{}:done", bare.id)))
        .collect();
    assert_eq!(asked.len(), 1);
    assert!(super::plans::told_for_test(&plan_row(&primary, bare.id).await).done);
    // A card raised before a restart cut off its link: linked, not raised
    // again.
    let orphan = match psvc::create(
        &primary.db.conn,
        psvc::NewPlan {
            bot_id: primary.bot().await,
            title: "Orphan".into(),
            goal: None,
            state: PlanState::Draft,
            origin_batch_id: None,
            for_input: None,
            origin_bot_id: None,
            origin_row_id: None,
            thread_id: None,
        },
        vec![psvc::NewStep::of(&plan_steps(&primary, id).await[0])],
        None,
        None,
    )
    .await
    .unwrap()
    {
        svc::Ledgered::New(p) => p,
        svc::Ledgered::Earlier(_) => unreachable!(),
    };
    let (raised, _) = svc::create_notice_with_row(
        &primary.db.conn,
        primary.bot().await,
        svc::NewNotice {
            kind: crate::db::entities::personal_agent_notice::NoticeKind::Plan,
            subject_key: Some(format!("plan:{}", orphan.id)),
            level: crate::db::entities::personal_agent_notice::NoticeLevel::Normal,
            batch_id: None,
            payload: json!({ "plan_id": orphan.id, "state": "draft" }),
        },
        NewRow::new(TimelineKind::Notice, "Plan"),
    )
    .await
    .unwrap();
    primary.plan_tick().await;
    assert_eq!(
        plan_row(&primary, orphan.id).await.notice_id,
        Some(raised.id)
    );
    let cards = notice_rows(&primary)
        .await
        .into_iter()
        .filter(|r| {
            data_of(r)["plan"]["id"] == json!(orphan.id)
                || r.ref_id.as_deref() == Some(&raised.id.to_string())
        })
        .count();
    assert_eq!(cards, 1, "one card for it");
    let (_, data) = plan_card(&primary, orphan.id).await;
    assert_eq!(
        data["plan"]["title"], "Orphan",
        "the linked card shows the plan"
    );
}

// ── 3.4: the nightly tidy-up and process skills (7.7, 7.8) ─────────────────

/// The owner's message delivered and its turn run to its end, the
/// assistant doing `work` in its working directory meanwhile.
async fn owner_said(
    engine: &Arc<PersonalAgentEngine>,
    rx: &mut tokio::sync::mpsc::Receiver<ConnectionCommand>,
    state: &State,
    conn: &str,
    said: &str,
    work: impl FnOnce(),
) -> i32 {
    let row = engine
        .send_owner_message(said.into(), Vec::new(), None)
        .await
        .unwrap();
    engine.pump().await;
    let (_, token) = take_prompt(rx);
    start_prompt(state, Some(&token)).await;
    work();
    emit(engine, state, conn, text("Noted."), true).await;
    emit(engine, state, conn, turn_complete("end_turn"), true).await;
    row.id
}

/// The internal turn the engine sends next: its prompt, run to its end
/// with the assistant doing `work`; its batch.
async fn internal_turn(
    engine: &Arc<PersonalAgentEngine>,
    rx: &mut tokio::sync::mpsc::Receiver<ConnectionCommand>,
    state: &State,
    conn: &str,
    work: impl FnOnce(),
) -> (String, i32) {
    engine.pump().await;
    let (prompt, token) = take_prompt(rx);
    start_prompt(state, Some(&token)).await;
    let batch = engine.current_batch().await.expect("a turn runs");
    work();
    emit(engine, state, conn, text("[[silent]]"), true).await;
    emit(engine, state, conn, turn_complete("end_turn"), true).await;
    (prompt, batch)
}

/// 03:00 of the owner's day `now` is in — still that day: it breaks at
/// 04:00.
async fn night_of(engine: &PersonalAgentEngine) -> chrono::DateTime<chrono::Utc> {
    let tz = engine.owner_tz().await;
    let day = super::presence::hours_day(super::clock::now(), tz) + chrono::Duration::days(1);
    super::due::local_at(tz, day.and_hms_opt(3, 0, 0).unwrap())
}

async fn tidy_events(host: &EngineHost) -> Vec<crate::db::entities::personal_agent_event::Model> {
    svc::events_in_flight(&host.db.conn, super::tidy::TIDY_EVENT)
        .await
        .unwrap()
}

async fn cards_of(
    engine: &PersonalAgentEngine,
    notice: &str,
) -> Vec<crate::db::entities::personal_agent_timeline::Model> {
    notice_rows(engine)
        .await
        .into_iter()
        .filter(|r| data_of(r)["notice"] == notice)
        .collect()
}

/// Until the last commit is one whose subject starts with `prefix` (the
/// owner's edits are committed off the call).
async fn wait_subject(dir: &std::path::Path, prefix: &str) {
    for _ in 0..100 {
        if head_subject(dir).await.starts_with(prefix) {
            return;
        }
        tokio::time::sleep(std::time::Duration::from_millis(20)).await;
    }
    panic!("no commit `{prefix}…`: {}", head_subject(dir).await);
}

async fn head_subject(dir: &std::path::Path) -> String {
    let out = std::process::Command::new("git")
        .args(["log", "-1", "--format=%s"])
        .current_dir(dir)
        .output()
        .unwrap();
    String::from_utf8_lossy(&out.stdout).trim().to_string()
}

/// Once the owner's day is over — 03:00 at the latest — each assistant with
/// something new since its last tidy-up is woken for one, one at a time: an
/// internal turn with its log, the owner's own words and its index, and no
/// reply shown. What it changed is one commit and one card, in the next
/// brief's own part, undone as a whole.
#[tokio::test]
async fn the_nightly_tidy_up_comes_once_the_day_is_over_one_at_a_time_and_is_undone_whole() {
    let (host, w, _tmp) = hosted().await;
    let primary = host.primary();
    primary.boot().await;
    let seg = open_segment(&primary).await;
    let (mut rx, state) = live_connection(&primary, seg, "pa-34a").await;
    let dir = workdir_now(&primary).await;
    let index = workdir::read_text(&dir, workdir::MEMORY_FILE);
    let rules = workdir::read_text(&dir, workdir::RULES_FILE);
    // The day: the owner said where they live now, and two entries say the
    // same old thing.
    let said = owner_said(
        &primary,
        &mut rx,
        &state,
        "pa-34a",
        "I moved to Berlin last week",
        || {
            workdir::write_file(
                &dir,
                "memory/home.md",
                "---\nname: home\ntype: fact\n---\nLives in Munich.\n",
            )
            .unwrap();
            workdir::write_file(
                &dir,
                "memory/city.md",
                "---\nname: city\ntype: fact\n---\nThe owner lives in Munich.\n",
            )
            .unwrap();
            workdir::write_file(
                &dir,
                workdir::MEMORY_FILE,
                &format!(
                    "{index}- [Home](memory/home.md) — Munich\n- [City](memory/city.md) — Munich\n"
                ),
            )
            .unwrap();
        },
    )
    .await;
    let before_index = workdir::read_text(&dir, workdir::MEMORY_FILE);
    let before_home = workdir::read_text(&dir, "memory/home.md");
    // The work assistant has something new too: the owner wrote to it.
    let worker = host.engine_for(Some(w)).await.unwrap();
    worker
        .send_owner_message("Remember the staging box".into(), Vec::new(), None)
        .await
        .unwrap();

    // The evening, their hours not known: not yet.
    host.tidy_tick(owner_time(&primary, 22 * 60).await).await;
    assert!(tidy_events(&host).await.is_empty());
    // 03:00: the primary first, alone.
    let night = night_of(&primary).await;
    host.tidy_tick(night).await;
    let flying = tidy_events(&host).await;
    assert_eq!(flying.len(), 1, "one at a time");
    assert_eq!(flying[0].bot_id, Some(primary.bot().await));
    host.tidy_tick(night + chrono::Duration::minutes(5)).await;
    assert_eq!(tidy_events(&host).await.len(), 1, "the next waits for it");

    let (prompt, batch) = internal_turn(&primary, &mut rx, &state, "pa-34a", || {
        std::fs::remove_file(dir.join("memory/city.md")).unwrap();
        workdir::write_file(
            &dir,
            "memory/home.md",
            "---\nname: home\ntype: fact\n---\nLives in Berlin (as of now).\n",
        )
        .unwrap();
        workdir::write_file(
            &dir,
            workdir::MEMORY_FILE,
            &format!("{index}- [Home](memory/home.md) — Berlin\n"),
        )
        .unwrap();
        workdir::write_file(
            &dir,
            workdir::RULES_FILE,
            &format!("{rules}Keep replies short.\n"),
        )
        .unwrap();
    })
    .await;
    assert!(prompt.contains("<codeg-tidy day=\""), "{prompt}");
    assert!(
        prompt.contains(&format!("[#{said} ")) && prompt.contains("I moved to Berlin last week"),
        "the owner's own words: {prompt}"
    );
    assert!(
        prompt.contains("- [City](memory/city.md) — Munich"),
        "the index: {prompt}"
    );
    assert!(prompt.contains("Update USER.md"), "{prompt}");
    assert!(
        prompt.contains("it is night: your memory is to be tidied up"),
        "{prompt}"
    );
    let bt = svc::get_batch(&host.db.conn, batch).await.unwrap().unwrap();
    assert_eq!(
        bt.trigger,
        Some(crate::db::entities::personal_agent_batch::BatchTrigger::Consolidate)
    );
    assert!(
        svc::reply_row_of_batch(&host.db.conn, batch)
            .await
            .unwrap()
            .is_none(),
        "no reply is shown"
    );

    // One commit, one card: low, made, and no memory card besides.
    assert!(head_subject(&dir)
        .await
        .starts_with("personal agent: tidy "));
    let cards = cards_of(&primary, "tidy").await;
    assert_eq!(cards.len(), 1);
    assert!(
        cards_of(&primary, "memory")
            .await
            .iter()
            .all(|c| c.batch_id != Some(batch)),
        "the tidy-up's card only"
    );
    let card = &cards[0];
    let data = data_of(card);
    assert_eq!(data["state"], "acted");
    assert!(card.body.starts_with("Tidied memory ("), "{}", card.body);
    assert!(
        card.body.contains("1 updated, 1 removed · rules"),
        "{}",
        card.body
    );
    let id = notice_id_of(card);
    let notice = svc::get_notice(&host.db.conn, id).await.unwrap().unwrap();
    assert_eq!(notice.kind, NoticeKind::Tidy);
    assert_eq!(notice.state, NoticeState::Acted);
    assert_eq!(
        notice.level,
        crate::db::entities::personal_agent_notice::NoticeLevel::Low
    );
    // The next look: the work assistant's turn now.
    host.tidy_tick(night + chrono::Duration::minutes(10)).await;
    let flying = tidy_events(&host).await;
    assert_eq!(flying.len(), 1);
    assert_eq!(flying[0].bot_id, Some(w));

    // Today lists it with its undo; the brief has it in a part of its own.
    let now = super::clock::now();
    let (today, _) = super::today::today(&host.db, &host.manager, now).await;
    let row = today
        .done
        .iter()
        .find(|r| r.kind == "tidy")
        .expect("in today");
    assert!(row.undo);
    assert_eq!(row.state.as_deref(), Some("acted"));
    let prefs = primary.prefs().await;
    let m = super::brief::gather(
        &host.db,
        &host.manager,
        "brief",
        now,
        now - chrono::Duration::hours(12),
        &prefs,
    )
    .await;
    assert_eq!(m.tidied.len(), 1, "{:?}", m.tidied);
    assert_eq!(m.tidied[0]["notice_id"], id);
    assert!(
        m.night.iter().all(|v| v["kind"] != "tidy"),
        "not again in the night's"
    );
    assert!(!m.is_empty());
    let text_of = super::brief::material_text(&m, primary.owner_tz().await);
    assert!(text_of.contains("Tidied their memory since"), "{text_of}");

    // Undo all: every file as it was before it, and the assistant told.
    let row = primary.act_on_notice(id, "undo").await.unwrap();
    assert_eq!(
        data_of(&svc::get_row(&host.db.conn, row.id).await.unwrap().unwrap())["state"],
        "undone"
    );
    assert!(dir.join("memory/city.md").is_file());
    assert_eq!(workdir::read_text(&dir, "memory/home.md"), before_home);
    assert_eq!(workdir::read_text(&dir, workdir::MEMORY_FILE), before_index);
    assert_eq!(workdir::read_text(&dir, workdir::RULES_FILE), rules);
    assert!(head_subject(&dir).await.starts_with("owner: undo tidy "));
    let told = svc::pending_events(&host.db.conn, primary.bot().await)
        .await
        .unwrap()
        .into_iter()
        .find(|e| e.summary.contains("undid your tidy-up"))
        .expect("told");
    assert!(!told.wake);
    assert!(
        SegmentState::parse(
            &svc::get_segment(&host.db.conn, seg)
                .await
                .unwrap()
                .unwrap()
                .state
        )
        .persona_resend,
        "its rules are handed over again"
    );
    assert!(primary.act_on_notice(id, "undo").await.is_err(), "once");
}

/// Nothing said and nothing written since the last tidy-up: no tidy-up.
/// With the owner's "don't", none at all.
#[tokio::test]
async fn nothing_new_no_tidy_up_and_with_it_off_none_at_all() {
    let (host, _w, _tmp) = hosted().await;
    let primary = host.primary();
    let night = night_of(&primary).await;
    host.tidy_tick(night).await;
    assert!(tidy_events(&host).await.is_empty(), "nothing new");
    primary
        .send_owner_message("hello".into(), Vec::new(), None)
        .await
        .unwrap();
    set_pref(&primary, "tidy", json!("off")).await;
    host.tidy_tick(night + chrono::Duration::minutes(5)).await;
    assert!(tidy_events(&host).await.is_empty(), "off");
    set_pref(&primary, "tidy", json!("auto")).await;
    host.tidy_tick(night + chrono::Duration::minutes(10)).await;
    assert_eq!(tidy_events(&host).await.len(), 1);
    // One of an earlier night that never came round is let go.
    let e = tidy_events(&host).await.remove(0);
    let tomorrow = night + chrono::Duration::days(1);
    host.tidy_tick(tomorrow).await;
    let flying = tidy_events(&host).await;
    assert!(
        flying.iter().all(|x| x.id != e.id),
        "the stale one is let go"
    );
}

/// With "show me first" the tidy-up is set aside at once: the memory as it
/// was, the card a draft — applied whole, or let go. A draft the memory
/// moved past is stale: nothing of it applied, and the next night tidies
/// again.
#[tokio::test]
async fn a_tidy_up_to_see_first_is_a_draft_applied_whole_or_stale() {
    let (host, _w, _tmp) = hosted().await;
    let primary = host.primary();
    primary.boot().await;
    set_pref(&primary, "tidy", json!("draft")).await;
    let seg = open_segment(&primary).await;
    let (mut rx, state) = live_connection(&primary, seg, "pa-34d").await;
    let dir = workdir_now(&primary).await;
    let index = workdir::read_text(&dir, workdir::MEMORY_FILE);
    owner_said(
        &primary,
        &mut rx,
        &state,
        "pa-34d",
        "We ship on Fridays",
        || {},
    )
    .await;
    let night = night_of(&primary).await;
    host.tidy_tick(night).await;
    internal_turn(&primary, &mut rx, &state, "pa-34d", || {
        workdir::write_file(
            &dir,
            "memory/ship.md",
            "---\nname: ship\ntype: fact\n---\nFridays.\n",
        )
        .unwrap();
        workdir::write_file(
            &dir,
            workdir::MEMORY_FILE,
            &format!("{index}- [Ship](memory/ship.md) — Fridays\n"),
        )
        .unwrap();
    })
    .await;
    // Set aside: the memory as it was.
    assert!(!dir.join("memory/ship.md").exists());
    assert_eq!(workdir::read_text(&dir, workdir::MEMORY_FILE), index);
    let card = cards_of(&primary, "tidy").await.remove(0);
    assert_eq!(data_of(&card)["state"], "draft");
    assert!(card.body.contains("a draft"), "{}", card.body);
    let id = notice_id_of(&card);
    assert_eq!(
        svc::get_notice(&host.db.conn, id)
            .await
            .unwrap()
            .unwrap()
            .state,
        NoticeState::Open
    );
    assert!(svc::pending_events(&host.db.conn, primary.bot().await)
        .await
        .unwrap()
        .iter()
        .any(|e| e.summary.contains("kept as a draft")));
    // It waits on the owner in "today".
    let (today, _) = super::today::today(&host.db, &host.manager, super::clock::now()).await;
    let row = today
        .needs
        .iter()
        .find(|r| r.kind == "tidy")
        .expect("waits on the owner");
    assert_eq!(row.state.as_deref(), Some("draft"));
    // The morning brief has it once it has waited a while: not just made;
    // in the next one when it was too new for the last; not again after.
    let made = row.at;
    let prefs = primary.prefs().await;
    let tidied_in = |now: chrono::DateTime<chrono::Utc>, since: chrono::DateTime<chrono::Utc>| {
        let host = host.clone();
        let prefs = prefs.clone();
        async move {
            super::brief::gather(&host.db, &host.manager, "brief", now, since, &prefs)
                .await
                .tidied
                .iter()
                .any(|v| v["notice_id"] == id)
        }
    };
    let min = chrono::Duration::minutes;
    assert!(!tidied_in(made + min(5), made - min(600)).await, "just made");
    assert!(tidied_in(made + min(45), made + min(5)).await, "too new for the last");
    assert!(!tidied_in(made + min(120), made + min(45)).await, "the last had it");
    // Applied: whole.
    let row = primary.act_on_notice(id, "apply").await.unwrap();
    assert_eq!(
        data_of(&svc::get_row(&host.db.conn, row.id).await.unwrap().unwrap())["state"],
        "applied"
    );
    assert!(dir.join("memory/ship.md").is_file());
    assert!(workdir::read_text(&dir, workdir::MEMORY_FILE)
        .contains("- [Ship](memory/ship.md) — Fridays"));
    assert!(head_subject(&dir).await.starts_with("owner: apply tidy "));
    assert!(primary.act_on_notice(id, "apply").await.is_err(), "once");
    // …and undone from there.
    primary.act_on_notice(id, "undo").await.unwrap();
    assert!(!dir.join("memory/ship.md").exists());

    // Another night's draft changes an entry the owner then writes
    // otherwise: stale.
    let entry = "---\nname: ship\ntype: fact\n---\nFridays.\n";
    primary.save_file("memory/ship.md", entry).await.unwrap();
    wait_subject(&dir, "owner: edit memory/ship.md").await;
    assert!(svc::insert_event(
        &host.db.conn,
        primary.bot().await,
        super::tidy::TIDY_EVENT,
        "tidy:2026-01-02",
        None,
        "Your nightly tidy-up of 2026-01-02 is due.".into(),
        Some(json!({ "day": "2026-01-02" })),
        true,
    )
    .await
    .unwrap());
    internal_turn(&primary, &mut rx, &state, "pa-34d", || {
        workdir::write_file(
            &dir,
            "memory/ship.md",
            &entry.replace("Fridays", "Thursdays"),
        )
        .unwrap();
    })
    .await;
    let draft = cards_of(&primary, "tidy")
        .await
        .into_iter()
        .find(|c| data_of(c)["day"] == "2026-01-02")
        .unwrap();
    assert_eq!(data_of(&draft)["state"], "draft");
    assert_eq!(
        workdir::read_text(&dir, "memory/ship.md"),
        entry,
        "set aside"
    );
    let mine = entry.replace("Fridays", "Mondays");
    primary.save_file("memory/ship.md", &mine).await.unwrap();
    wait_subject(&dir, "owner: edit memory/ship.md").await;
    let id = notice_id_of(&draft);
    let row = primary.act_on_notice(id, "apply").await.unwrap();
    assert_eq!(
        data_of(&svc::get_row(&host.db.conn, row.id).await.unwrap().unwrap())["state"],
        "stale"
    );
    assert_eq!(
        workdir::read_text(&dir, "memory/ship.md"),
        mine,
        "the owner's edit stays"
    );
    assert_eq!(
        svc::get_notice(&host.db.conn, id)
            .await
            .unwrap()
            .unwrap()
            .state,
        NoticeState::Expired
    );
    // The next night tidies again: the stale draft is new since the last
    // tidy-up that ran — and only until the next one runs.
    let since = primary.tidy_since(super::clock::now()).await;
    assert!(
        primary.has_new_content(since).await,
        "a stale draft is tidied again"
    );
    assert!(
        !primary
            .has_new_content(super::clock::now() + chrono::Duration::hours(1))
            .await,
        "once"
    );
    // A draft let go.
    let _ = primary
        .act_on_notice(id, "dismiss")
        .await
        .expect_err("a stale one is no draft");
}

/// Work of its own that got done since its last tidy-up is something new
/// to tidy by — handed out before or since — and its tidy-up lists it, with
/// the step that brings its persona's head up to date; codeg's checks are
/// not its work.
#[tokio::test]
async fn work_done_since_the_last_tidy_up_is_new_content_and_listed_for_it() {
    let (engine, tmp) = ready().await;
    let made = engine.create_bot(BotSpec::named("Dev")).await.unwrap();
    let worker = engine_of(&engine, &tmp, made.bot.id);
    let since = super::clock::now() - chrono::Duration::seconds(1);
    assert!(!worker.has_new_content(since).await, "nothing yet");
    let check = session_dispatch(&worker, DispatchState::Completed, "c-check").await;
    crate::db::entities::personal_agent_dispatch::Entity::update_many()
        .col_expr(
            crate::db::entities::personal_agent_dispatch::Column::IsCheck,
            sea_orm::sea_query::Expr::value(true),
        )
        .col_expr(
            crate::db::entities::personal_agent_dispatch::Column::Title,
            sea_orm::sea_query::Expr::value("A check"),
        )
        .filter(crate::db::entities::personal_agent_dispatch::Column::Id.eq(check))
        .exec(&engine.db.conn)
        .await
        .unwrap();
    assert!(!worker.has_new_content(since).await, "a check is codeg's");
    session_dispatch(&worker, DispatchState::Running, "c-running").await;
    assert!(!worker.has_new_content(since).await, "not done yet");
    session_dispatch(&worker, DispatchState::Completed, "c-done").await;
    assert!(worker.has_new_content(since).await, "work done");
    assert!(
        !worker
            .has_new_content(super::clock::now() + chrono::Duration::hours(1))
            .await,
        "only since"
    );
    svc::insert_event(
        &engine.db.conn,
        made.bot.id,
        super::tidy::TIDY_EVENT,
        "tidy:2026-11-20",
        None,
        "tidy".into(),
        Some(json!({ "day": "2026-11-20", "since": since })),
        true,
    )
    .await
    .unwrap();
    let e = svc::pending_events(&engine.db.conn, made.bot.id)
        .await
        .unwrap()
        .into_iter()
        .find(|e| e.kind == super::tidy::TIDY_EVENT)
        .unwrap();
    let block = worker.tidy_block(&e).await;
    assert!(block.contains("<codeg-work-done>\n["), "{block}");
    assert!(block.contains("] Investigate\n</codeg-work-done>"), "{block}");
    assert!(!block.contains("A check"), "{block}");
    assert!(block.contains("Bring the first lines of SOUL.md"), "{block}");
}

/// Work for one request of the owner's that went well — three pieces, all
/// done, quiet a while — is looked back at once, by the assistant it was
/// for, with codeg's record of it. The skill it writes is installed into
/// its brain's skills and shown on a card: turned off and on, a change of
/// it (after the owner's own edit) undone, deleted.
#[tokio::test]
async fn work_that_went_well_becomes_a_process_skill_installed_turned_off_changed_and_deleted() {
    let (host, _w, _tmp) = hosted().await;
    let primary = host.primary();
    primary.boot().await;
    let seg = open_segment(&primary).await;
    let (mut rx, state) = live_connection(&primary, seg, "pa-34r").await;
    let dir = workdir_now(&primary).await;
    let asked = owner_said(
        &primary,
        &mut rx,
        &state,
        "pa-34r",
        "Cut the 1.2 release",
        || {},
    )
    .await;
    role_assistant(&primary, "Releaser", true).await;
    let mut ids = Vec::new();
    for title in ["Write the notes", "Fix the red CI", "Tag rc1"] {
        let d = svc::create_dispatch(
            &host.db.conn,
            NewDispatch {
                bot_id: primary.bot().await,
                mode: DispatchMode::Chat,
                work_snapshot_json: "{}".into(),
                folder_id: None,
                deliverable: None,
                title: title.into(),
                prompt: format!("{title}, please."),
                origin_batch_id: None,
                on_done: None,
                lineage: svc::Lineage {
                    origin_bot_id: Some(primary.bot().await),
                    origin_row_id: Some(asked),
                    ..Default::default()
                },
                done_when: None,
                pr_fix: None,
                is_check: false,
            },
        )
        .await
        .unwrap();
        svc::update_dispatch(
            &host.db.conn,
            d.id,
            None,
            DispatchWrite {
                state: Some(DispatchState::Completed),
                result_excerpt: Some(Some(format!("{title}: done"))),
                ..Default::default()
            },
        )
        .await
        .unwrap();
        ids.push(d.id);
    }
    // Just done: not yet.
    let now = super::clock::now();
    host.reflect_tick(now).await;
    assert!(
        svc::events_in_flight(&host.db.conn, super::skills::REFLECT_EVENT)
            .await
            .unwrap()
            .is_empty()
    );
    // Quiet for a while: the primary looks back (no release assistant).
    host.reflect_tick(now + chrono::Duration::minutes(40)).await;
    let flying = svc::events_in_flight(&host.db.conn, super::skills::REFLECT_EVENT)
        .await
        .unwrap();
    assert_eq!(flying.len(), 1);
    assert_eq!(flying[0].bot_id, Some(primary.bot().await));
    let skill_md = "---\nname: release\ndescription: when the owner says release\n---\n# Release\n\n1. Notes — Releaser, chat.\n2. Stop for the owner before the tag.\n";
    let (prompt, batch) = internal_turn(&primary, &mut rx, &state, "pa-34r", || {
        workdir::write_file(&dir, "process-skills/release/SKILL.md", skill_md).unwrap();
    })
    .await;
    assert!(prompt.contains("<codeg-reflect>"), "{prompt}");
    assert!(
        prompt.contains("3 pieces of work handed out for one request"),
        "{prompt}"
    );
    assert!(
        prompt.contains(&format!("The owner asked (#{asked}"))
            && prompt.contains("Cut the 1.2 release"),
        "{prompt}"
    );
    assert!(
        prompt.contains(&format!(
            "\"Fix the red CI\" — {} · chat · done in 1 round",
            super::messages::display_name(&primary.agent_row().await.unwrap())
        )),
        "{prompt}"
    );
    assert!(prompt.contains("Came back: Tag rc1: done"), "{prompt}");
    assert!(
        prompt.contains("work you were responsible for went well"),
        "{prompt}"
    );
    let bt = svc::get_batch(&host.db.conn, batch).await.unwrap().unwrap();
    assert_eq!(
        bt.trigger,
        Some(crate::db::entities::personal_agent_batch::BatchTrigger::Reflect)
    );
    assert!(svc::reply_row_of_batch(&host.db.conn, batch)
        .await
        .unwrap()
        .is_none());
    assert!(head_subject(&dir)
        .await
        .starts_with(&format!("personal agent: look back at request #{asked}")));
    // Looked back at once.
    host.reflect_tick(now + chrono::Duration::minutes(50)).await;
    assert!(
        svc::events_in_flight(&host.db.conn, super::skills::REFLECT_EVENT)
            .await
            .unwrap()
            .is_empty()
    );

    // Installed, with a card.
    let installed = dir.join(".claude/skills/release/SKILL.md");
    assert_eq!(std::fs::read_to_string(&installed).unwrap(), skill_md);
    assert!(workdir::skill_installed(
        &dir,
        AgentType::ClaudeCode,
        "release"
    ));
    let card = cards_of(&primary, "skill").await.remove(0);
    let data = data_of(&card);
    assert_eq!(
        (
            data["state"].as_str(),
            data["status"].as_str(),
            data["title"].as_str(),
            data["name"].as_str()
        ),
        (
            Some("acted"),
            Some("added"),
            Some("Release"),
            Some("release")
        )
    );
    assert_eq!(data["description"], "when the owner says release");
    assert!(card.body.contains("learned"), "{}", card.body);
    let id = notice_id_of(&card);
    // A new session's handoff names it.
    let switches = super::engine::skill_switches(&primary.agent_row().await.unwrap());
    let lines = super::skills::skills_lines(
        &workdir::process_skills(&dir),
        &workdir::loadable_skills(&dir, &switches),
    );
    assert!(
        lines.contains("- release — when the owner says release (process-skills/release/SKILL.md)"),
        "{lines}"
    );

    // Off: not loaded, kept; on again.
    primary.act_on_notice(id, "disable").await.unwrap();
    assert!(!installed.exists());
    assert!(dir.join("process-skills/release/SKILL.md").is_file());
    let files =
        crate::commands::personal_agent::personal_agent_files_core(&host.db, &host.data_dir, None)
            .await
            .unwrap();
    assert!(files
        .iter()
        .any(|f| f.name == "process-skills/release/SKILL.md" && f.off));
    assert_eq!(
        data_of(&svc::get_row(&host.db.conn, card.id).await.unwrap().unwrap())["off"],
        true
    );
    primary.act_on_notice(id, "enable").await.unwrap();
    assert!(installed.is_file());

    // The owner edits it: installed as they wrote it.
    let mine = skill_md.replace(
        "Stop for the owner before the tag.",
        "Stop for me before the tag and before publishing.",
    );
    primary
        .save_file("process-skills/release/SKILL.md", &mine)
        .await
        .unwrap();
    assert_eq!(std::fs::read_to_string(&installed).unwrap(), mine);
    wait_subject(&dir, "owner: edit process-skills/release").await;
    // The assistant changes it again: at once, with a diff card.
    let theirs = mine.replace("1. Notes", "1. Release notes");
    owner_said(
        &primary,
        &mut rx,
        &state,
        "pa-34r",
        "Call them release notes",
        || {
            workdir::write_file(&dir, "process-skills/release/SKILL.md", &theirs).unwrap();
        },
    )
    .await;
    assert_eq!(std::fs::read_to_string(&installed).unwrap(), theirs);
    let changed = cards_of(&primary, "skill")
        .await
        .into_iter()
        .find(|c| data_of(c)["status"] == "modified")
        .expect("a diff card");
    assert!(data_of(&changed)["diff"]
        .as_str()
        .unwrap()
        .contains("+1. Release notes"));
    primary
        .act_on_notice(notice_id_of(&changed), "undo")
        .await
        .unwrap();
    assert_eq!(
        std::fs::read_to_string(&installed).unwrap(),
        mine,
        "back to the owner's"
    );

    // Deleted: gone, its card says so.
    primary.act_on_notice(id, "delete").await.unwrap();
    assert!(!dir.join("process-skills/release").exists());
    assert!(!installed.exists());
    assert_eq!(
        data_of(&svc::get_row(&host.db.conn, card.id).await.unwrap().unwrap())["state"],
        "deleted"
    );
    assert!(svc::pending_events(&host.db.conn, primary.bot().await)
        .await
        .unwrap()
        .iter()
        .any(|e| e.summary.contains("deleted your process skill release")));
}

/// Three pieces of work for one request are looked back at by the one that
/// led them; two pieces of work that went as two did before, for a request like it, are
/// looked back at too; work that failed is not.
#[tokio::test]
async fn a_chain_is_looked_back_at_by_its_lead_and_the_same_steps_twice_too() {
    let (host, _w, _tmp) = hosted().await;
    let primary = host.primary();
    let exec = role_assistant(&primary, "Runner", true).await;
    let me = primary.bot().await;
    async fn chain(
        host: &EngineHost,
        bot: i32,
        _exec: i32,
        row: i32,
        steps: &[(&str, DispatchState)],
    ) {
        for (title, st) in steps {
            let d = svc::create_dispatch(
                &host.db.conn,
                NewDispatch {
                    bot_id: bot,
                    mode: DispatchMode::Chat,
                    work_snapshot_json: "{}".into(),
                    folder_id: None,
                    deliverable: None,
                    title: (*title).into(),
                    prompt: "do".into(),
                    origin_batch_id: None,
                    on_done: None,
                    lineage: svc::Lineage {
                        origin_bot_id: Some(bot),
                        origin_row_id: Some(row),
                        ..Default::default()
                    },
                    done_when: None,
                    pr_fix: None,
                    is_check: false,
                },
            )
            .await
            .unwrap();
            svc::update_dispatch(
                &host.db.conn,
                d.id,
                None,
                DispatchWrite {
                    state: Some(*st),
                    ..Default::default()
                },
            )
            .await
            .unwrap();
        }
    }
    let owner_row = |text: &'static str| {
        let p = primary.clone();
        async move {
            p.send_owner_message(text.into(), Vec::new(), None)
                .await
                .unwrap()
                .id
        }
    };
    let r1 = owner_row("Ship 1.3").await;
    chain(
        &host,
        me,
        exec,
        r1,
        &[
            ("notes", DispatchState::Completed),
            ("tag", DispatchState::Completed),
            ("docker", DispatchState::Completed),
        ],
    )
    .await;
    let r2 = owner_row("Check the deps for security updates").await;
    chain(
        &host,
        me,
        exec,
        r2,
        &[
            ("scan deps", DispatchState::Completed),
            ("write up", DispatchState::Completed),
        ],
    )
    .await;
    let r3 = owner_row("Check the deps for security updates again").await;
    chain(
        &host,
        me,
        exec,
        r3,
        &[
            ("scan deps", DispatchState::Completed),
            ("write up", DispatchState::Completed),
        ],
    )
    .await;
    let r4 = owner_row("Fix the flaky test").await;
    chain(
        &host,
        me,
        exec,
        r4,
        &[
            ("fix", DispatchState::Completed),
            ("verify", DispatchState::Failed),
            ("again", DispatchState::Completed),
        ],
    )
    .await;

    host.reflect_tick(super::clock::now() + chrono::Duration::minutes(40))
        .await;
    let flying = svc::events_in_flight(&host.db.conn, super::skills::REFLECT_EVENT)
        .await
        .unwrap();
    let of = |row: i32| {
        flying
            .iter()
            .find(|e| super::skills::origin_of_event(e) == Some(row))
    };
    assert_eq!(of(r1).and_then(|e| e.bot_id), Some(me), "three pieces: its lead");
    assert!(of(r2).is_none(), "the first time: no");
    let again = of(r3).expect("the same steps again");
    assert_eq!(again.bot_id, Some(me));
    let p: serde_json::Value = serde_json::from_str(again.payload.as_deref().unwrap()).unwrap();
    assert_eq!(p["before"]["origin_row"], r2);
    assert!(of(r4).is_none(), "one failed");
    assert_eq!(flying.len(), 2);
    // Off: none.
    let (host2, _w2, _tmp2) = hosted().await;
    set_pref(&host2.primary(), "tidy", json!("off")).await;
    host2
        .reflect_tick(super::clock::now() + chrono::Duration::minutes(40))
        .await;
    assert!(
        svc::events_in_flight(&host2.db.conn, super::skills::REFLECT_EVENT)
            .await
            .unwrap()
            .is_empty()
    );
}

/// With "show me first", a skill the assistant writes is set aside: not in
/// its folder, not installed, until the owner installs it.
#[tokio::test]
async fn a_skill_to_see_first_is_installed_only_when_the_owner_says() {
    let (engine, _tmp) = configured().await;
    set_pref(&engine, "tidy", json!("draft")).await;
    let seg = open_segment(&engine).await;
    let (mut rx, state) = live_connection(&engine, seg, "pa-34s").await;
    let dir = workdir_now(&engine).await;
    owner_said(
        &engine,
        &mut rx,
        &state,
        "pa-34s",
        "From now on, do releases like this",
        || {
            workdir::write_file(
                &dir,
                "process-skills/release/SKILL.md",
                "---\nname: release\ndescription: releases\n---\n# Release\n",
            )
            .unwrap();
        },
    )
    .await;
    assert!(
        !dir.join("process-skills/release/SKILL.md").exists(),
        "set aside"
    );
    assert!(!workdir::skill_installed(
        &dir,
        AgentType::ClaudeCode,
        "release"
    ));
    let card = cards_of(&engine, "skill").await.remove(0);
    assert_eq!(data_of(&card)["state"], "draft");
    let id = notice_id_of(&card);
    engine.act_on_notice(id, "apply").await.unwrap();
    assert!(dir.join("process-skills/release/SKILL.md").is_file());
    assert!(workdir::skill_installed(
        &dir,
        AgentType::ClaudeCode,
        "release"
    ));
    assert_eq!(
        data_of(
            &svc::get_row(&engine.db.conn, card.id)
                .await
                .unwrap()
                .unwrap()
        )["state"],
        "applied"
    );
}

/// A skill's draft installed while the assistant's turn has the same skill
/// changed and not committed: what the owner approved is the draft as
/// committed, so the turn's change — set aside as it settles — never makes
/// the skill drop out; and the skill loads, exactly as approved, once that
/// change is gone, whether set aside or dropped by the assistant itself.
#[tokio::test]
async fn a_skill_approved_mid_turn_is_the_committed_draft_and_loads_once_the_turn_is_done() {
    for dropped in [false, true] {
        let (engine, _tmp) = configured().await;
        let seg = open_segment(&engine).await;
        let (mut rx, state) = live_connection(&engine, seg, "pa-34m").await;
        let dir = workdir_now(&engine).await;
        let skill = "process-skills/release/SKILL.md";
        let v1 = "---\nname: release\ndescription: releases\n---\n# Release\n\nstep one\n\nstep three\n";
        let v2 = v1.replace("step one", "step ONE");
        let v2c = v2.replace("step three", "step THREE");
        owner_said(&engine, &mut rx, &state, "pa-34m", "Do releases like this", || {
            workdir::write_file(&dir, skill, v1).unwrap();
        })
        .await;
        assert!(workdir::skill_installed(&dir, AgentType::ClaudeCode, "release"));
        set_pref(&engine, "tidy", json!("draft")).await;
        owner_said(&engine, &mut rx, &state, "pa-34m", "Change step one", || {
            workdir::write_file(&dir, skill, &v2).unwrap();
        })
        .await;
        assert_eq!(workdir::read_text(&dir, skill), v1, "set aside");
        let card = cards_of(&engine, "skill")
            .await
            .into_iter()
            .find(|c| data_of(c)["state"] == "draft")
            .expect("a draft");
        // Mid-turn: the assistant changes another step of the same skill.
        workdir::write_file(&dir, skill, &v1.replace("step three", "step THREE")).unwrap();
        engine.act_on_notice(notice_id_of(&card), "apply").await.unwrap();
        assert_eq!(workdir::read_text(&dir, skill), v2c, "the draft and the turn's change");
        let row = engine.agent_row().await.unwrap();
        assert_eq!(
            super::engine::skill_switches(&row).approved.get("release"),
            Some(&workdir::content_hash(&v2)),
            "approved as committed"
        );
        // The turn settles: its change set aside (show me first), or
        // dropped by the assistant before it ends.
        owner_said(&engine, &mut rx, &state, "pa-34m", "ok", || {
            if dropped {
                workdir::write_file(&dir, skill, &v2).unwrap();
            }
        })
        .await;
        assert_eq!(workdir::read_text(&dir, skill), v2, "dropped: {dropped}");
        assert!(
            workdir::skill_installed(&dir, AgentType::ClaudeCode, "release"),
            "dropped: {dropped}"
        );
        let installed = crate::commands::acp::scoped_skill_dirs(
            AgentType::ClaudeCode,
            crate::acp::types::AgentSkillScope::Project,
            Some(&dir.to_string_lossy()),
        )
        .unwrap()
        .remove(0)
        .join("release")
        .join("SKILL.md");
        assert_eq!(std::fs::read_to_string(installed).unwrap(), v2, "dropped: {dropped}");
    }
}

/// A skill change undone while the assistant's turn has another line of
/// the skill changed and not committed: what is approved is the undo as
/// committed, not the turn's line with it.
#[tokio::test]
async fn a_skill_undone_mid_turn_is_approved_as_committed() {
    let (engine, _tmp) = configured().await;
    let seg = open_segment(&engine).await;
    let (mut rx, state) = live_connection(&engine, seg, "pa-34p").await;
    let dir = workdir_now(&engine).await;
    let skill = "process-skills/release/SKILL.md";
    let v1 = "---\nname: release\ndescription: releases\n---\n# Release\n\nstep one\n\nstep three\n";
    let v2 = v1.replace("step one", "step ONE");
    owner_said(&engine, &mut rx, &state, "pa-34p", "Do releases like this", || {
        workdir::write_file(&dir, skill, v1).unwrap();
    })
    .await;
    owner_said(&engine, &mut rx, &state, "pa-34p", "Change step one", || {
        workdir::write_file(&dir, skill, &v2).unwrap();
    })
    .await;
    let card = cards_of(&engine, "skill")
        .await
        .into_iter()
        .rfind(|c| data_of(c)["state"] == "acted")
        .expect("the change's card");
    workdir::write_file(&dir, skill, &v2.replace("step three", "step THREE")).unwrap();
    engine.act_on_notice(notice_id_of(&card), "undo").await.unwrap();
    assert_eq!(workdir::read_text(&dir, skill), v1.replace("step three", "step THREE"));
    let row = engine.agent_row().await.unwrap();
    assert_eq!(
        super::engine::skill_switches(&row).approved.get("release"),
        Some(&workdir::content_hash(v1)),
        "the undo as committed"
    );
}

/// The owner saves a skill between a turn's commit and its cards: the
/// turn's version, older, is not approved over the owner's.
#[tokio::test]
async fn a_turns_skill_approval_never_overrides_a_newer_owner_save() {
    let (engine, _tmp) = configured().await;
    let dir = workdir_now(&engine).await;
    let skill = "process-skills/release/SKILL.md";
    let theirs = "---\nname: release\ndescription: releases\n---\n# Release\n\nthe turn's\n";
    let mine = "---\nname: release\ndescription: releases\n---\n# Release\n\nthe owner's\n";
    workdir::write_file(&dir, skill, theirs).unwrap();
    let done = workdir::commit_turn(&dir, "turn", |_| false, "aside").await.unwrap();
    engine.save_file(skill, mine).await.unwrap();
    engine.skill_cards(&dir, &done, None, None).await;
    let row = engine.agent_row().await.unwrap();
    assert_eq!(
        super::engine::skill_switches(&row).approved.get("release"),
        Some(&workdir::content_hash(mine))
    );
    assert!(workdir::skill_installed(&dir, AgentType::ClaudeCode, "release"));
}

/// A skill the history does not hold (an ignore rule keeps it out), saved
/// by the owner, turned off and on again: still approved as it is, still
/// installed.
#[tokio::test]
async fn an_ignored_skill_turned_off_and_on_stays_approved() {
    let (engine, _tmp) = configured().await;
    let dir = workdir_now(&engine).await;
    let ignore = format!("{}/process-skills/\n", workdir::read_text(&dir, ".gitignore"));
    std::fs::write(dir.join(".gitignore"), ignore).unwrap();
    let skill = "process-skills/release/SKILL.md";
    let text = "---\nname: release\ndescription: releases\n---\n# Release\n";
    engine.save_file(skill, text).await.unwrap();
    assert!(workdir::skill_installed(&dir, AgentType::ClaudeCode, "release"));
    engine.switch_skill("release", false).await.unwrap();
    assert!(!workdir::skill_installed(&dir, AgentType::ClaudeCode, "release"));
    engine.switch_skill("release", true).await.unwrap();
    let row = engine.agent_row().await.unwrap();
    assert_eq!(
        super::engine::skill_switches(&row).approved.get("release"),
        Some(&workdir::content_hash(text))
    );
    assert!(workdir::skill_installed(&dir, AgentType::ClaudeCode, "release"));
}

/// Bringing the installed skills in line reads the settings only once it
/// holds the lock: one that was waiting while the owner turned a skill off
/// does not put it back.
#[tokio::test]
async fn a_skill_sync_waiting_while_the_owner_turns_a_skill_off_leaves_it_off() {
    let (engine, _tmp) = configured().await;
    let seg = open_segment(&engine).await;
    let (mut rx, state) = live_connection(&engine, seg, "pa-34n").await;
    let dir = workdir_now(&engine).await;
    owner_said(&engine, &mut rx, &state, "pa-34n", "Do releases like this", || {
        workdir::write_file(
            &dir,
            "process-skills/release/SKILL.md",
            "---\nname: release\ndescription: releases\n---\n# Release\n",
        )
        .unwrap();
    })
    .await;
    assert!(workdir::skill_installed(&dir, AgentType::ClaudeCode, "release"));
    let held = engine.skill_sync_lock.lock().await;
    let e = engine.clone();
    let sync = tokio::spawn(async move { e.resync_skill().await });
    tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    let row = engine.agent_row().await.unwrap();
    svc::patch_settings(
        &engine.db.conn,
        row.id,
        &json!({ super::engine::SKILLS_OFF_KEY: { "release": true } }),
    )
    .await
    .unwrap();
    drop(held);
    sync.await.unwrap();
    assert!(!workdir::skill_installed(&dir, AgentType::ClaudeCode, "release"));
}

/// The owner's edit on the page waits for any other write of the
/// directory — an undo, a draft applied, a turn's commit — and is written
/// and committed in one hold of it: nothing written meanwhile writes over it.
#[tokio::test]
async fn the_owners_page_edit_waits_for_any_other_write_of_the_directory() {
    let (engine, _tmp) = configured().await;
    let dir = workdir_now(&engine).await;
    let mine = "# Rules\n\n- Mine.\n";
    let held = workdir::hold_writes_for_test().await;
    let e = engine.clone();
    let save = tokio::spawn(async move { e.save_file(workdir::RULES_FILE, mine).await });
    tokio::time::sleep(std::time::Duration::from_millis(150)).await;
    assert_ne!(
        workdir::read_text(&dir, workdir::RULES_FILE),
        mine,
        "not written while another write holds the directory"
    );
    drop(held);
    save.await.unwrap().unwrap();
    assert_eq!(workdir::read_text(&dir, workdir::RULES_FILE), mine);
    assert!(
        head_subject(&dir)
            .await
            .starts_with("owner: edit AGENTS.md"),
        "and committed with it"
    );
}

/// A tidy-up or a look back queued before the owner switched them off is
/// let go, not sent; one switched off while it ran is kept aside — a draft
/// on its card — not taken in.
#[tokio::test]
async fn switched_off_a_queued_tidy_up_is_let_go_and_one_running_is_kept_aside() {
    let (engine, _tmp) = configured().await;
    let seg = open_segment(&engine).await;
    let (mut rx, state) = live_connection(&engine, seg, "pa-34o").await;
    let dir = workdir_now(&engine).await;
    let index = workdir::read_text(&dir, workdir::MEMORY_FILE);
    let queue = |key: &'static str, kind: &'static str| {
        let e = engine.clone();
        async move {
            assert!(svc::insert_event(
                &e.db.conn,
                e.bot().await,
                kind,
                key,
                None,
                "due".into(),
                Some(json!({ "day": "2026-01-03", "origin_row": 1 })),
                true,
            )
            .await
            .unwrap());
        }
    };
    queue("tidy:2026-01-03", super::tidy::TIDY_EVENT).await;
    queue("reflect:1:1", super::skills::REFLECT_EVENT).await;
    set_pref(&engine, "tidy", json!("off")).await;
    engine.pump().await;
    assert!(no_prompt(&mut rx), "nothing sent");
    let left = svc::pending_events(&engine.db.conn, engine.bot().await)
        .await
        .unwrap();
    assert!(
        left.iter()
            .all(|e| e.kind != super::tidy::TIDY_EVENT && e.kind != super::skills::REFLECT_EVENT),
        "let go: {left:?}"
    );

    // Running when it is switched off: what it changed is kept aside.
    set_pref(&engine, "tidy", json!("auto")).await;
    queue("tidy:2026-01-04", super::tidy::TIDY_EVENT).await;
    engine.pump().await;
    let (prompt, token) = take_prompt(&mut rx);
    assert!(prompt.contains("<codeg-tidy"), "{prompt}");
    start_prompt(&state, Some(&token)).await;
    workdir::write_file(
        &dir,
        workdir::MEMORY_FILE,
        &format!("{index}- [X](memory/x.md) — x\n"),
    )
    .unwrap();
    set_pref(&engine, "tidy", json!("off")).await;
    emit(&engine, &state, "pa-34o", text("[[silent]]"), true).await;
    emit(&engine, &state, "pa-34o", turn_complete("end_turn"), true).await;
    assert_eq!(
        workdir::read_text(&dir, workdir::MEMORY_FILE),
        index,
        "not taken in"
    );
    let card = cards_of(&engine, "tidy").await.remove(0);
    assert_eq!(data_of(&card)["state"], "draft");
}

